/// Root/QC-admitted, exactly executed clean system-Agent journal bootstrap.
///
/// Storage may inspect this closure, but cannot manufacture one from a merely
/// self-canonical genesis record or decoded authority evidence.
pub struct ReplaySealedGenesis {
    genesis: AgentJournalGenesis,
    post_create: RuntimeState,
    empty_frontier: MergeFrontier,
    ordered_invocations: InvocationIndexManifest,
    merge_invocations: InvocationIndexManifest,
    local_invocations: InvocationIndexManifest,
    artifacts: ArtifactClosure,
    root_anchor: RootAnchorRecord,
    root_admission_record: SystemAgentGenesisAdmissionRecord,
    admission_record: AgentGenesisAdmissionRecord,
    admission_evidence: SystemAgentGenesisEvidence,
    replica: AgentReplica,
}

impl ReplaySealedGenesis {
    pub fn genesis(&self) -> &AgentJournalGenesis {
        &self.genesis
    }

    pub fn post_create(&self) -> &RuntimeState {
        &self.post_create
    }

    pub fn empty_frontier(&self) -> &MergeFrontier {
        &self.empty_frontier
    }

    pub fn ordered_invocations(&self) -> &InvocationIndexManifest {
        &self.ordered_invocations
    }

    pub fn merge_invocations(&self) -> &InvocationIndexManifest {
        &self.merge_invocations
    }

    pub fn local_invocations(&self) -> &InvocationIndexManifest {
        &self.local_invocations
    }

    pub fn artifacts(&self) -> &ArtifactClosure {
        &self.artifacts
    }

    pub fn root_anchor(&self) -> &RootAnchorRecord {
        &self.root_anchor
    }

    pub fn admission_record(&self) -> &AgentGenesisAdmissionRecord {
        &self.admission_record
    }

    /// Typed inner root admission. This is distinct from the tagged outer
    /// journal admission whose ID is committed by [`AgentJournalGenesis`].
    pub const fn root_admission_record(&self) -> &SystemAgentGenesisAdmissionRecord {
        &self.root_admission_record
    }

    pub fn root_admission_id(&self) -> SystemAgentGenesisAdmissionId {
        self.root_admission_record.id()
    }

    pub fn admission_evidence(&self) -> &SystemAgentGenesisEvidence {
        &self.admission_evidence
    }

    pub fn admission_commitment(&self) -> Hash {
        self.genesis.admission.as_hash()
    }

    /// Mint replay provenance from the complete root-reverified seal. This
    /// is deliberately the only production constructor for the opaque root
    /// journal identity.
    pub(crate) fn replayed_root_identity(
        &self,
    ) -> Result<ReplayedRootJournalIdentity, ReplayValidationError> {
        let AgentGenesisAdmissionRecord::RootBootstrap(root_admission) = &self.admission_record
        else {
            return Err(ReplayError::ScopeMismatch);
        };
        if root_admission != &self.root_admission_record
            || self.admission_record.id() != self.genesis.admission
            || root_admission.root_anchor() != self.root_anchor.id()
            || root_admission.root_anchor_config_version() != self.root_anchor.config_version()
            || root_admission.root_anchor_config() != self.root_anchor.config_commitment()
            || root_admission.evidence() != self.admission_evidence.id()
        {
            return Err(ReplayError::ScopeMismatch);
        }
        Ok(ReplayedRootJournalIdentity {
            genesis: self.genesis.id(),
            outer_admission: self.genesis.admission,
        })
    }

    /// Derive the signer-independent durable authority route from this exact
    /// root-admitted seal. Host cannot assemble a route from raw IDs or a
    /// decoded state independently of the opaque replay provenance.
    #[cfg(all(feature = "std", feature = "storage"))]
    pub(crate) fn system_authority_ledger_route(
        &self,
    ) -> Result<SystemAuthorityLedgerRoute, ReplayValidationError> {
        let identity = self.replayed_root_identity()?;
        let scope = SystemAuthorityJournalScope::from_replayed_root(&identity)
            .map_err(|_| ReplayError::ScopeMismatch)?;
        let decoded = decode_standard_runtime_state(&self.post_create)
            .map_err(|_| ReplayError::ScopeMismatch)?;
        let authority = decoded
            .system_authority
            .as_ref()
            .ok_or(ReplayError::ScopeMismatch)?;
        if authority.system_agent() != self.genesis.runtime().agent {
            return Err(ReplayError::ScopeMismatch);
        }
        SystemAuthorityLedgerRoute::from_authenticated_replay(scope, authority)
            .map_err(|_| ReplayError::ScopeMismatch)
    }

    pub const fn replica(&self) -> AgentReplica {
        self.replica
    }

    /// Mint the sole production bootstrap capability from a root/QC-verified
    /// system-Agent admission and the exact replayed Create transition.
    /// Decoded evidence, a self-canonical genesis, or caller-supplied state is
    /// never sufficient on its own.
    pub(crate) fn from_prepared_verified(
        verified: &VerifiedSystemAgentGenesis,
        admission_evidence: SystemAgentGenesisEvidence,
        prepared: ReplayPreparedGenesis,
    ) -> Result<Self, ReplayValidationError> {
        let ReplayOperation::CleanManage {
            request: crate::agent_sdk::ManagementRequest::Create(descriptor),
            ..
        } = &prepared.create.operation
        else {
            return Err(ReplayError::InvalidRecord);
        };
        if !super::bootstrap::descriptor_matches_root_replica(descriptor, prepared.replica) {
            return Err(ReplayError::InvalidRecord);
        }
        let authority_binding = Hash(descriptor.authority.commitment().0);
        let root_admission = verified.admission_record();
        let root_anchor = verified.root_anchor().clone();
        if root_admission.evidence() != verified.evidence_id()
            || root_admission.root_anchor() != root_anchor.id()
            || root_admission.root_anchor_config_version() != root_anchor.config_version()
            || root_admission.root_anchor_config() != root_anchor.config_commitment()
            || admission_evidence.id() != verified.evidence_id()
            || verified.space() != prepared.create.runtime.space
            || verified.system_agent() != prepared.create.runtime.agent
            || verified.authority_binding() != authority_binding
            || verified.genesis_intent() != prepared.expectations.genesis_intent()
            || verified.runtime_binding() != prepared.expectations.runtime_binding()
            || verified.post_create_state() != prepared.expectations.post_create_state()
            || verified.artifact_closure() != prepared.expectations.artifact_closure()
            || verified.sequence() != prepared.expectations.sequence()
        {
            return Err(ReplayError::InvalidRecord);
        }

        let admission_record = AgentGenesisAdmissionRecord::root_bootstrap(root_admission)
            .map_err(|_| ReplayError::InvalidRecord)?;
        let root_admission_id = root_admission.id();
        let journal_admission_id = admission_record.id();
        if root_admission_id == SystemAgentGenesisAdmissionId::ZERO
            || journal_admission_id == AgentGenesisAdmissionId::ZERO
            || journal_admission_id.as_bytes() == root_admission_id.as_bytes()
        {
            return Err(ReplayError::InvalidRecord);
        }

        let genesis = AgentJournalGenesis {
            admission: journal_admission_id,
            create: prepared.create,
        };
        genesis.validate().map_err(|_| ReplayError::InvalidRecord)?;
        if verified.admission_commitment() != root_admission.id().as_hash()
            || admission_record.id() != genesis.admission
            || genesis
                .genesis_intent()
                .map_err(|_| ReplayError::InvalidRecord)?
                != verified.genesis_intent()
            || genesis
                .genesis_authority_sequence()
                .map_err(|_| ReplayError::InvalidRecord)?
                != verified.sequence()
        {
            return Err(ReplayError::InvalidRecord);
        }
        let genesis_id = genesis.id();
        if genesis_id == AgentJournalGenesisId::ZERO {
            return Err(ReplayError::InvalidRecord);
        }
        let artifacts = ArtifactClosure {
            genesis: genesis_id,
            artifacts: prepared.artifacts,
        };
        artifacts
            .validate()
            .map_err(|_| ReplayError::InvalidRecord)?;
        if artifacts
            .system_genesis_commitment()
            .map_err(|_| ReplayError::InvalidRecord)?
            != verified.artifact_closure()
        {
            return Err(ReplayError::InvalidRecord);
        }
        let post_create = prepared.post_create;
        let replica = prepared.replica;
        let empty_frontier = MergeFrontier {
            genesis: genesis_id,
            events: Vec::new(),
        };
        Ok(Self {
            genesis,
            post_create,
            empty_frontier,
            ordered_invocations: InvocationIndexManifest::empty(
                genesis_id,
                InvocationOwnershipScope::Ordered,
            ),
            merge_invocations: InvocationIndexManifest::empty(
                genesis_id,
                InvocationOwnershipScope::Merge,
            ),
            local_invocations: InvocationIndexManifest::empty(
                genesis_id,
                InvocationOwnershipScope::Local(replica.node),
            ),
            artifacts,
            root_anchor,
            root_admission_record: root_admission,
            admission_record,
            admission_evidence,
            replica,
        })
    }

    pub fn lane_manifest(&self, lane: PersistedLane) -> LaneStateManifest {
        let cursor = match lane {
            PersistedLane::Control | PersistedLane::Linear => LaneCursor::Ordered {
                base: OrderedBase::post_genesis(),
            },
            PersistedLane::Merge => LaneCursor::Merge {
                frontier: self.empty_frontier.id(),
            },
            PersistedLane::Local => LaneCursor::Local {
                node: self.replica.node,
                revision: 0,
                head: None,
            },
        };
        LaneStateManifest {
            #[cfg(feature = "experimental-state-blocks")]
            external_root: None,
            genesis: self.genesis.id(),
            runtime: self.genesis.runtime().clone(),
            lane,
            cursor,
            state: BlobRef::of_bytes(state_component(&self.post_create, lane)),
        }
    }

    pub fn initial_heads(&self) -> JournalHeads {
        JournalHeads::initial(
            self.genesis.id(),
            self.genesis.admission,
            self.replica.node,
            self.empty_frontier.id(),
            self.genesis.runtime().clone(),
        )
    }
}

impl ReplaySealedOrdinaryGenesis for ReplaySealedGenesis {
    fn genesis(&self) -> &AgentJournalGenesis {
        self.genesis()
    }

    fn post_create(&self) -> &RuntimeState {
        self.post_create()
    }

    fn empty_frontier(&self) -> &MergeFrontier {
        self.empty_frontier()
    }

    fn ordered_invocations(&self) -> &InvocationIndexManifest {
        self.ordered_invocations()
    }

    fn merge_invocations(&self) -> &InvocationIndexManifest {
        self.merge_invocations()
    }

    fn local_invocations(&self) -> &InvocationIndexManifest {
        self.local_invocations()
    }

    fn artifacts(&self) -> &ArtifactClosure {
        self.artifacts()
    }

    fn replica(&self) -> AgentReplica {
        self.replica()
    }

    fn admission_commitment(&self) -> Hash {
        self.admission_commitment()
    }

    fn lane_manifest(&self, lane: PersistedLane) -> LaneStateManifest {
        self.lane_manifest(lane)
    }

    fn initial_heads(&self) -> JournalHeads {
        self.initial_heads()
    }

    fn validates_post_create_state(&self) -> bool {
        let ReplayOperation::CleanManage {
            request: crate::agent_sdk::ManagementRequest::Create(descriptor),
            ..
        } = &self.genesis.create.operation
        else {
            return false;
        };
        !self.post_create.is_empty()
            && super::bootstrap::descriptor_matches_root_replica(descriptor, self.replica)
    }

    fn admission_record(&self) -> Option<&AgentGenesisAdmissionRecord> {
        Some(&self.admission_record)
    }

    fn validate_seal(&self) -> Result<(), ReplayValidationError> {
        self.replayed_root_identity()?;
        let claim = self.admission_evidence.claim();
        if self.admission_evidence.validate().is_err()
            || claim.space() != self.genesis.runtime().space
            || claim.system_agent() != self.genesis.runtime().agent
            || claim.authority_binding() != self.root_anchor.authority_binding()
            || claim.root_certification() != self.root_anchor.root_certification()
            || claim.post_create_state()
                != system_genesis_post_create_state_commitment(&self.post_create)
                    .map_err(|_| ReplayError::InvalidRecord)?
            || claim.artifact_closure()
                != self
                    .artifacts
                    .system_genesis_commitment()
                    .map_err(|_| ReplayError::InvalidRecord)?
            || self
                .admission_evidence
                .certificate()
                .verify(
                    self.root_anchor.initial_committee(),
                    claim.authority_claim(),
                )
                .is_err()
            || !self.validates_post_create_state()
        {
            return Err(ReplayError::ScopeMismatch);
        }
        Ok(())
    }
}

/// Replay-authenticated closure of one checkpoint publication.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReplaySealedCheckpoint {
    manifest: CheckpointManifest,
    lanes: Vec<(CheckpointLane, LaneStateManifest)>,
    artifacts: ArtifactClosure,
    invocation_indexes: Vec<(InvocationIndexId, InvocationIndexManifest)>,
    local_cursors: Vec<(NodeId, u64, Option<LocalEntryId>)>,
    fence_ancestry: FenceAncestryEvidence,
}

impl ReplaySealedCheckpoint {
    pub fn manifest(&self) -> &CheckpointManifest {
        &self.manifest
    }

    pub fn lanes(&self) -> &[(CheckpointLane, LaneStateManifest)] {
        &self.lanes
    }

    pub fn artifacts(&self) -> &ArtifactClosure {
        &self.artifacts
    }

    pub fn invocation_indexes(&self) -> &[(InvocationIndexId, InvocationIndexManifest)] {
        &self.invocation_indexes
    }

    pub fn local_cursors(&self) -> &[(NodeId, u64, Option<LocalEntryId>)] {
        &self.local_cursors
    }

    pub(crate) const fn fence_ancestry(&self) -> &FenceAncestryEvidence {
        &self.fence_ancestry
    }
}

/// Replay-proven ancestry of the latest lifecycle fence relative to the
/// current checkpoint boundary.
///
/// The ordered head content ID is already a commitment to its parent chain;
/// this opaque evidence binds that anchor to the exact checkpoint base and
/// fence after deterministic replay. Local cold recovery treats the owned
/// descriptor store's published checkpoint as its trust root. Shared mode
/// must authenticate [`Self::commitment`] with its ordered-snapshot Raft QC.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct FenceAncestryEvidence {
    // Process-local proof metadata, excluded from the stable commitment.
    // Only a verified common checkpoint can separate physical replay and
    // semantic ancestry boundaries for a sealed publication.
    common_checkpoint: Option<CheckpointId>,
    genesis: AgentJournalGenesisId,
    checkpoint_base: OrderedBase,
    canonical_head: OrderedBase,
    fence: OrderedBase,
    ordered_anchor: Hash,
}

impl FenceAncestryEvidence {
    #[cfg(feature = "std")]
    fn from_common_checkpoint(
        claim: &super::shared_commit::SharedAgentCommonSnapshotClaim,
        checkpoint: CheckpointId,
    ) -> Self {
        let ordered = claim.ordered();
        Self {
            common_checkpoint: Some(checkpoint),
            genesis: ordered.genesis(),
            checkpoint_base: claim.ancestry().checkpoint_base(),
            canonical_head: ordered.ordered(),
            fence: ordered.merge_fence(),
            ordered_anchor: claim.ancestry().ordered_anchor(),
        }
    }

    fn post_genesis(genesis: AgentJournalGenesisId) -> Result<Self, ReplayValidationError> {
        if genesis == AgentJournalGenesisId::ZERO {
            return Err(ReplayError::InvalidFence);
        }
        Ok(Self {
            common_checkpoint: None,
            genesis,
            checkpoint_base: OrderedBase::post_genesis(),
            canonical_head: OrderedBase::post_genesis(),
            fence: OrderedBase::post_genesis(),
            ordered_anchor: Hash::digest(
                b"vos/agent/replay/genesis-ordered-ancestry",
                &[&genesis.0],
            ),
        })
    }

    /// Restore the transitive ancestry proof carried by an exact checkpoint
    /// selected by the currently durable Local descriptor head. This is not a
    /// raw checkpoint validator: the caller must first prove `heads` is the
    /// store-owned current trust root and load the exact referenced closure.
    /// Shared mode must replace this Local trust step with a verified QC.
    fn from_published_local_checkpoint(
        heads: &JournalHeads,
        checkpoint_id: CheckpointId,
        checkpoint: &CheckpointManifest,
    ) -> Result<Self, ReplayValidationError> {
        let checkpoint_base = OrderedBase {
            index: checkpoint.ordered_index,
            head: checkpoint.ordered_head,
        };
        if heads.validate().is_err()
            || checkpoint.validate().is_err()
            || heads.checkpoint != Some(checkpoint_id)
            || checkpoint.id() != checkpoint_id
            || heads.genesis != checkpoint.genesis
            || checkpoint_base.validate().is_err()
            || checkpoint.merge_fence.validate().is_err()
            || checkpoint.merge_fence.index > checkpoint_base.index
            || (checkpoint.merge_fence.index == checkpoint_base.index
                && checkpoint.merge_fence.head != checkpoint_base.head)
        {
            return Err(ReplayError::InvalidFence);
        }
        let checkpoint_bytes = ordered_base_evidence_bytes(checkpoint_base);
        Ok(Self {
            common_checkpoint: None,
            genesis: checkpoint.genesis,
            checkpoint_base,
            canonical_head: checkpoint_base,
            fence: checkpoint.merge_fence,
            ordered_anchor: Hash::digest(
                b"vos/agent/replay/local-checkpoint-trust-root",
                &[&checkpoint_id.0, &checkpoint_bytes],
            ),
        })
    }

    /// Advance ancestry by one already-validated canonical OrderedEntry.
    fn advance_ordered(
        &self,
        entry: &OrderedEntry,
        next_fence: OrderedBase,
    ) -> Result<Self, ReplayValidationError> {
        let id = entry.id();
        let canonical_head = OrderedBase {
            index: entry.index,
            head: Some(id),
        };
        let advances_fence = next_fence == canonical_head;
        if !self.validate()
            || entry.validate().is_err()
            || entry.genesis != self.genesis
            || entry.parent != self.canonical_head.head
            || entry.index
                != self
                    .canonical_head
                    .index
                    .checked_add(1)
                    .ok_or(ReplayError::ReplayLimit)?
            || next_fence.validate().is_err()
            || advances_fence != entry.merge_seal.is_some()
            || (!advances_fence && next_fence != self.fence)
        {
            return Err(ReplayError::InvalidFence);
        }
        let index = entry.index.to_le_bytes();
        Ok(Self {
            common_checkpoint: self.common_checkpoint,
            genesis: self.genesis,
            checkpoint_base: self.checkpoint_base,
            canonical_head,
            fence: next_fence,
            ordered_anchor: Hash::digest(
                b"vos/agent/replay/ordered-ancestry-step",
                &[&self.ordered_anchor.0, &id.0, &index],
            ),
        })
    }

    fn checkpointed(&self) -> Result<Self, ReplayValidationError> {
        if !self.validate() {
            return Err(ReplayError::InvalidFence);
        }
        let base = ordered_base_evidence_bytes(self.canonical_head);
        Ok(Self {
            common_checkpoint: None,
            genesis: self.genesis,
            checkpoint_base: self.canonical_head,
            canonical_head: self.canonical_head,
            fence: self.fence,
            ordered_anchor: Hash::digest(
                b"vos/agent/replay/checkpoint-ordered-ancestry",
                &[&self.commitment().0, &base],
            ),
        })
    }

    pub(crate) const fn genesis(&self) -> AgentJournalGenesisId {
        self.genesis
    }

    pub(crate) const fn common_checkpoint(&self) -> Option<CheckpointId> {
        self.common_checkpoint
    }

    pub(crate) const fn checkpoint_base(&self) -> OrderedBase {
        self.checkpoint_base
    }

    pub(crate) const fn canonical_head(&self) -> OrderedBase {
        self.canonical_head
    }

    pub(crate) const fn fence(&self) -> OrderedBase {
        self.fence
    }

    pub(crate) fn commitment(&self) -> Hash {
        let checkpoint_bytes = ordered_base_evidence_bytes(self.checkpoint_base);
        let canonical_bytes = ordered_base_evidence_bytes(self.canonical_head);
        let fence_bytes = ordered_base_evidence_bytes(self.fence);
        Hash::digest(
            b"vos/agent/replay/fence-ancestry-evidence",
            &[
                &self.genesis.0,
                &checkpoint_bytes,
                &canonical_bytes,
                &fence_bytes,
                &self.ordered_anchor.0,
            ],
        )
    }

    pub(crate) fn validate(&self) -> bool {
        self.genesis != AgentJournalGenesisId::ZERO
            && self.checkpoint_base.validate().is_ok()
            && self.canonical_head.validate().is_ok()
            && self.fence.validate().is_ok()
            && self.checkpoint_base.index <= self.canonical_head.index
            && (self.checkpoint_base.index != self.canonical_head.index
                || self.checkpoint_base.head == self.canonical_head.head)
            && self.fence.index <= self.canonical_head.index
            && (self.fence.index != self.canonical_head.index
                || self.fence.head == self.canonical_head.head)
            && self.ordered_anchor != Hash::ZERO
            && self.commitment() != Hash::ZERO
    }
}

fn ordered_base_evidence_bytes(base: OrderedBase) -> [u8; 41] {
    let mut bytes = [0_u8; 41];
    bytes[0] = u8::from(base.head.is_some());
    bytes[1..9].copy_from_slice(&base.index.to_le_bytes());
    if let Some(head) = base.head {
        bytes[9..].copy_from_slice(&head.0);
    }
    bytes
}

/// Opaque authority required by the journal store's public CAS operation.
///
/// Shared ordered publications are the one exception to the local journal's
/// usual `entry.merge_frontier == current.merge_frontier` shape.  The mode is
/// private to replay and storage: callers cannot turn a generic/raw journal
/// anchor into a state splice.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReplayPublicationMode {
    Canonical,
    SharedOrderedPreserveMerge,
    SharedOrderedInstallFence,
}

/// Opaque evidence that an exact Shared Ordered entry crossed the durable
/// Raft-log commit boundary. Replay deliberately accepts neither a bare entry
/// nor an application QC here: replicas first apply the committed log slot,
/// then certify the exact replay-derived projection. A durable exact
/// reservation is irrevocable: a later divergent reservation fail-stops new
/// work but cannot revoke a bearer which may already have crossed journal
/// CAS; the ledger still permits that originally stored exact reservation to
/// consume into its one anchor.
#[derive(Debug)]
pub(crate) struct CommittedSharedOrdered {
    reservation: ReservedAgentRaftApplication,
    entry: OrderedEntry,
    route: AgentRouteKey,
    raft_index: u64,
    raft_term: u64,
    raft_payload_commitment: Hash,
    journal_store: JournalStoreInstanceId,
    local_node: NodeId,
    committee: AgentReplicaCommittee,
}

impl CommittedSharedOrdered {
    /// Bridge seam for an exact command read from the durable committed Raft
    /// log and the independently admitted committee named by its route.
    pub(crate) fn from_reserved_raft_application(
        reserved: ReservedAgentRaftApplication,
        trusted_committee: &AgentReplicaCommittee,
        #[cfg(feature = "storage")] validated_batch: Option<ValidatedSharedArtifactBatch>,
    ) -> Result<Self, ReplayValidationError> {
        let committed = reserved.committed();
        let AgentRaftCommand::Ordered {
            route,
            artifact_batch,
            entry,
        } = committed.command()
        else {
            return Err(ReplayError::InvalidRecord);
        };
        #[cfg(feature = "storage")]
        let staged_batch_matches = match (artifact_batch, validated_batch.as_ref()) {
            (None, None) => true,
            (Some(expected), Some(validated)) => {
                *expected == validated.batch() && *route == validated.route()
            }
            _ => false,
        };
        #[cfg(not(feature = "storage"))]
        let staged_batch_matches = artifact_batch.is_none();
        if !staged_batch_matches
            || *artifact_batch != reserved.artifact_batch()
            || entry.validate().is_err()
            || route.validate().is_err()
            || route.genesis() != entry.genesis
            || route.space() != entry.input.runtime.space
            || route.agent() != entry.input.runtime.agent
            || route.committee() != trusted_committee.id()
            || trusted_committee.profile() != AgentProfile::Shared
            || route.space() != trusted_committee.space()
            || route.agent() != trusted_committee.agent()
            || committed.index() == 0
            || committed.term() == 0
            || committed.committed_index() < committed.index()
            || committed.payload_commitment() == Hash::ZERO
            || trusted_committee
                .member_by_node(reserved.local_node())
                .is_none()
        {
            return Err(ReplayError::InvalidRecord);
        }
        let entry = entry.clone();
        let route = *route;
        let raft_index = committed.index();
        let raft_term = committed.term();
        let raft_payload_commitment = committed.payload_commitment();
        let journal_store = reserved.journal_store();
        let local_node = reserved.local_node();
        Ok(Self {
            reservation: reserved,
            entry,
            route,
            raft_index,
            raft_term,
            raft_payload_commitment,
            journal_store,
            local_node,
            committee: trusted_committee.clone(),
        })
    }

    fn authenticated_entry(&self) -> Result<&OrderedEntry, ReplayValidationError> {
        let AgentRaftCommand::Ordered {
            route,
            artifact_batch,
            entry,
        } = self.reservation.committed().command()
        else {
            return Err(ReplayError::InvalidRecord);
        };
        if *artifact_batch != self.reservation.artifact_batch()
            || route != &self.route
            || entry != &self.entry
            || self.entry.validate().is_err()
            || self.route.validate().is_err()
            || self.route.genesis() != self.entry.genesis
            || self.route.space() != self.entry.input.runtime.space
            || self.route.agent() != self.entry.input.runtime.agent
            || self.route.committee() != self.committee.id()
            || self.committee.profile() != AgentProfile::Shared
            || self.raft_index == 0
            || self.raft_term == 0
            || self.raft_payload_commitment == Hash::ZERO
            || self.reservation.journal_store() != self.journal_store
            || self.committee.member_by_node(self.local_node).is_none()
            || self.reservation.route() != self.route
            || self.reservation.index() != self.raft_index
            || self.reservation.term() != self.raft_term
            || self.reservation.payload_commitment() != self.raft_payload_commitment
            || self.reservation.local_node() != self.local_node
        {
            Err(ReplayError::InvalidRecord)
        } else {
            Ok(&self.entry)
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReplaySealedPublication {
    /// Exact candidate changes, not proof of durable availability. Ordinary
    /// publishers refuse this plan until an exclusive availability owner stages
    /// its closure. Boxed so opaque/Attested publication stacks do not grow.
    #[cfg(feature = "experimental-state-blocks")]
    external_execution: Option<Box<ReplayExternalExecution>>,
    expected: JournalHeadsId,
    next: JournalHeads,
    anchor: ReplayPublicationAnchor,
    outcomes: Vec<ReplaySealedOutcome>,
    history_plans: Vec<InvocationHistoryWritePlan>,
    proof_requirements: Vec<ReplayTransitionProofRequirement>,
    transition_proof_retirements: Vec<ReplayTransitionProofRetirement>,
    transition_proof_actions: Vec<ReplayTransitionProofAction>,
    /// Replay-authenticated live projection at the newest Merge fence (or
    /// checkpoint when no later fence exists). Storage uses this private,
    /// non-wire boundary together with the canonical retained suffix to
    /// independently re-derive every ordered proof action.
    transition_proof_boundary: ReplayTransitionProofShadow,
    checkpoint: Option<ReplaySealedCheckpoint>,
    shared_merge_projection: Option<ReplaySealedSharedMergeProjection>,
    shared_ordered_commit: Option<ReplaySealedSharedOrderedCommit>,
    system_authority_write: Option<ReplaySystemAuthorityWrite>,
    #[cfg(feature = "std")]
    transition_proof_batch: Option<StagedTransitionProofBatch>,
    fence_ancestry: FenceAncestryEvidence,
    mode: ReplayPublicationMode,
}

/// Exact replay positions which executed in Attested mode and therefore must
/// be covered, in canonical execution order, by the thin staged proof batch.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ReplayTransitionProofRequirement {
    binding: ReplayTransitionProofBinding,
    intent: ReplayTransitionProofIntent,
    lifecycle: ReplayTransitionProofLifecycle,
    projection_action: ReplayTransitionProofProjectionAction,
}

/// Replay-sealed authority to retire one exact live proof edge. Merge events
/// only contribute this value while an Ordered fence is finalizing their
/// canonical replay; provisional Merge publication therefore cannot mint an
/// irreversible acknowledgement tombstone.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ReplayTransitionProofRetirement {
    input: ReplayInputId,
    position: ReplayPosition,
    key: crate::agent_sdk::proof::TransitionProofKey,
}

/// An Applied acknowledgement in an unfenced Merge suffix. It consumes the
/// logical proof edge for subsequent canonical replay, but cannot remove the
/// physical live pointer or mint permanent retirement history until an
/// Ordered fence finalizes the suffix.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ReplayTransitionProofAcknowledgement {
    input: ReplayInputId,
    position: ReplayPosition,
    key: crate::agent_sdk::proof::TransitionProofKey,
}

impl ReplayTransitionProofAcknowledgement {
    pub(crate) const fn input(self) -> ReplayInputId {
        self.input
    }

    pub(crate) const fn position(self) -> ReplayPosition {
        self.position
    }

    pub(crate) const fn key(self) -> crate::agent_sdk::proof::TransitionProofKey {
        self.key
    }
}

impl ReplayTransitionProofRetirement {
    pub(crate) const fn input(self) -> ReplayInputId {
        self.input
    }

    pub(crate) const fn position(self) -> ReplayPosition {
        self.position
    }

    pub(crate) const fn key(self) -> crate::agent_sdk::proof::TransitionProofKey {
        self.key
    }
}

/// Replay-owned meaning of one proof-index projection change. Lifecycle
/// publications bind the exact condition encoded by their input. A Merge
/// rebuild instead consumes whatever exact live edge is authenticated by the
/// CAS predecessor; the staged batch may report that value but cannot choose
/// it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReplayTransitionProofIntent {
    FirstPublication,
    Resume(crate::agent_sdk::proof::TransitionProofKey),
    Recanonicalize,
}

/// Exact lifecycle condition carried by the replay input. It remains explicit
/// during Merge recanonicalization even though storage derives the concrete
/// live edge to replace from the authenticated CAS predecessor.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReplayTransitionProofLifecycle {
    Invoke,
    Resume(crate::agent_sdk::proof::TransitionProofKey),
    Acknowledge(crate::agent_sdk::proof::TransitionProofKey),
}

/// An Attested lifecycle operation whose encoded live-edge condition did not
/// match the authenticated boundary-relative proof projection. Replay emits
/// a deterministic no-op without running the guest or consulting a proof
/// provider; storage re-derives the mismatch from the same canonical suffix.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ReplayTransitionProofStale {
    input: ReplayInputId,
    position: ReplayPosition,
    lifecycle: ReplayTransitionProofLifecycle,
}

impl ReplayTransitionProofStale {
    pub(crate) const fn input(self) -> ReplayInputId {
        self.input
    }

    pub(crate) const fn position(self) -> ReplayPosition {
        self.position
    }

    pub(crate) const fn lifecycle(self) -> ReplayTransitionProofLifecycle {
        self.lifecycle
    }
}

/// Canonical transition-proof lifecycle effects in exact replay order. A
/// single Merge/fence CAS may interleave publications, acknowledgements, and
/// stale no-ops for the same invocation; separate per-kind vectors cannot
/// authenticate that sequence without changing its meaning.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReplayTransitionProofAction {
    Requirement(ReplayTransitionProofRequirement),
    Acknowledgement(ReplayTransitionProofAcknowledgement),
    Retirement(ReplayTransitionProofRetirement),
    Stale(ReplayTransitionProofStale),
}

/// Effect an authenticated requirement may have on the proof live map.
/// Shared Ordered preservation replays the pinned Merge dependency only to
/// validate its existing records; changing live pointers there would roll the
/// physical Merge frontier back from G to the older pinned frontier F.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReplayTransitionProofProjectionAction {
    UpdateLive,
    ValidateOnly,
}

impl ReplayTransitionProofRequirement {
    pub(crate) const fn input(self) -> super::journal::ReplayInputId {
        self.binding.input()
    }

    pub(crate) const fn position(self) -> ReplayPosition {
        self.binding.position()
    }

    pub(crate) const fn binding(self) -> ReplayTransitionProofBinding {
        self.binding
    }

    pub(crate) const fn intent(self) -> ReplayTransitionProofIntent {
        self.intent
    }

    pub(crate) const fn lifecycle(self) -> ReplayTransitionProofLifecycle {
        self.lifecycle
    }

    pub(crate) const fn projection_action(self) -> ReplayTransitionProofProjectionAction {
        self.projection_action
    }

    pub(crate) const fn projection(self) -> ReplayTransitionProofProjection {
        self.binding.projection()
    }
}

/// Replay-authenticated pre-transition Merge(F) projection retained as an
/// immutable publication dependency for Shared exact retry and recovery.
///
/// This is deliberately not a public wire capability: only the Shared replay
/// path can place it inside a sealed publication, and storage validates and
/// persists it before making the successor heads visible.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct ReplaySealedSharedMergeProjection {
    manifest: LaneStateManifest,
    state: Vec<u8>,
}

impl ReplaySealedSharedMergeProjection {
    pub(crate) const fn manifest(&self) -> &LaneStateManifest {
        &self.manifest
    }

    pub(crate) fn state(&self) -> &[u8] {
        &self.state
    }
}

/// Full deterministic claim derived while applying one durable Shared Raft
/// slot. Storage binds it immutably to the Ordered entry before the successor
/// head CAS so a crash between publication and ledger anchoring is retryable.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct ReplaySealedSharedOrderedCommit {
    journal_store: JournalStoreInstanceId,
    claim: OrderedCommitClaim,
    raft_payload_commitment: Hash,
}

impl ReplaySealedSharedOrderedCommit {
    pub(crate) const fn journal_store(&self) -> JournalStoreInstanceId {
        self.journal_store
    }

    pub(crate) const fn claim(&self) -> &OrderedCommitClaim {
        &self.claim
    }

    pub(crate) const fn raft_payload_commitment(&self) -> Hash {
        self.raft_payload_commitment
    }
}

/// Opaque proof that one exact replay-derived Shared projection is visible at
/// the journal head. The evidence ledger accepts this receipt, never a raw
/// caller-supplied claim.
#[derive(Debug)]
pub(crate) struct PublishedSharedOrdered {
    journal_store: JournalStoreInstanceId,
    claim: OrderedCommitClaim,
    entry: OrderedEntryId,
    successor: JournalHeadsId,
    raft_payload_commitment: Hash,
    reservation: ReservedAgentRaftApplication,
}

impl PublishedSharedOrdered {
    pub(crate) const fn journal_store(&self) -> JournalStoreInstanceId {
        self.journal_store
    }

    pub(crate) const fn claim(&self) -> &OrderedCommitClaim {
        &self.claim
    }

    pub(crate) const fn entry(&self) -> OrderedEntryId {
        self.entry
    }

    pub(crate) const fn successor(&self) -> JournalHeadsId {
        self.successor
    }

    pub(crate) const fn raft_index(&self) -> u64 {
        self.claim.raft_index()
    }

    pub(crate) const fn raft_term(&self) -> u64 {
        self.claim.raft_term()
    }

    pub(crate) const fn raft_payload_commitment(&self) -> Hash {
        self.raft_payload_commitment
    }

    pub(crate) const fn reservation(&self) -> &ReservedAgentRaftApplication {
        &self.reservation
    }

    #[cfg(feature = "std")]
    fn from_binding(
        binding: &ReplaySealedSharedOrderedCommit,
        successor: JournalHeadsId,
        authority: CommittedSharedOrdered,
    ) -> Result<Self, JournalStoreError> {
        let entry = binding
            .claim
            .ordered()
            .head
            .ok_or(JournalStoreError::NonCanonical)?;
        if binding.claim.validate().is_err()
            || successor == JournalHeadsId::ZERO
            || binding.raft_payload_commitment == Hash::ZERO
            || binding.journal_store != authority.journal_store
            || binding.claim.genesis() != authority.route.genesis()
            || binding.claim.admission() != authority.route.admission()
            || binding.claim.committee() != authority.route.committee()
            || binding.claim.raft_index() != authority.raft_index
            || binding.claim.raft_term() != authority.raft_term
            || entry != authority.entry.id()
            || binding.raft_payload_commitment != authority.raft_payload_commitment
        {
            return Err(JournalStoreError::NonCanonical);
        }
        Ok(Self {
            journal_store: binding.journal_store,
            claim: binding.claim.clone(),
            entry,
            successor,
            raft_payload_commitment: binding.raft_payload_commitment,
            reservation: authority.reservation,
        })
    }
}

/// Exact input/outcome pair authenticated by replay and installed before the
/// successor ownership root becomes visible.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReplaySealedOutcome {
    record: InvocationOutcomeRecord,
    input: ReplayInput,
}

impl ReplaySealedOutcome {
    pub fn record(&self) -> &InvocationOutcomeRecord {
        &self.record
    }

    pub fn input(&self) -> &ReplayInput {
        &self.input
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MaterializedOrderedSnapshot {
    #[cfg(feature = "experimental-state-blocks")]
    linear_root: Option<super::journal::ExternalStateRoot>,
    runtime: RuntimeBinding,
    control: Vec<u8>,
    linear: Vec<u8>,
}

#[cfg(feature = "experimental-state-blocks")]
impl MaterializedOrderedSnapshot {
    /// Cache consistency only. The source owner must authenticate the full
    /// root context and origin before constructing this private snapshot.
    fn validate(&self, base: OrderedBase) -> Result<(), ReplayValidationError> {
        if let Some(root) = &self.linear_root {
            base.validate()
                .map_err(|_| ReplayError::InvalidOrderedBase)?;
            let scope = root.descriptor.context().scope();
            let LaneCursor::Ordered { base: origin } = root.cursor else {
                return Err(ReplayError::InvalidOrderedBase);
            };
            if root.runtime.validate().is_err()
                || root.runtime.space != self.runtime.space
                || root.runtime.agent != self.runtime.agent
                || scope.space().0 != self.runtime.space.0
                || scope.agent().0 != self.runtime.agent.0
                || scope.lane() != crate::agent_sdk::StateLane::Linear
                || origin.validate().is_err()
                || origin.index > base.index
                || (origin.index == base.index && origin != base)
                || root.descriptor.encode() != self.linear
            {
                return Err(ReplayError::InvalidOrderedBase);
            }
        }
        Ok(())
    }
}

const MAX_MATERIALIZED_ORDERED_SNAPSHOTS: usize = MAX_REPLAY_SUFFIX_ENTRIES + 1;
const MAX_MATERIALIZED_ORDERED_SNAPSHOT_BYTES: usize = MAX_REPLAY_SUFFIX_BYTES;

/// Bounded authenticated cache of the Control/Linear images needed by the
/// current replay suffix. Checkpoint compaction retains only the current
/// ordered base; any older base must be supplied by the certified resolver.
/// Variable image bytes have a separate aggregate budget; fixed runtime/root
/// metadata is bounded by the maximum snapshot count and owns no block payloads.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct MaterializedOrderedSnapshots {
    values: BTreeMap<OrderedBase, MaterializedOrderedSnapshot>,
    bytes: usize,
}

/// Exact native system-authority side product reconstructed while replaying
/// the current canonical Ordered head. This is process-local evidence inside
/// an authenticated materialization, never a persisted or caller-supplied
/// backwards state transition.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ReplayMaterializedSystemAuthorityWrite {
    entry: OrderedEntry,
    write: ReplaySystemAuthorityWrite,
}

impl MaterializedOrderedSnapshots {
    fn get(&self, base: &OrderedBase) -> Option<&MaterializedOrderedSnapshot> {
        self.values.get(base)
    }

    fn iter(&self) -> impl Iterator<Item = (&OrderedBase, &MaterializedOrderedSnapshot)> {
        self.values.iter()
    }

    fn len(&self) -> usize {
        self.values.len()
    }

    fn insert(
        &mut self,
        base: OrderedBase,
        snapshot: MaterializedOrderedSnapshot,
    ) -> Result<(), ReplayValidationError> {
        #[cfg(feature = "experimental-state-blocks")]
        snapshot.validate(base)?;
        let snapshot_bytes = snapshot
            .control
            .len()
            .checked_add(snapshot.linear.len())
            .ok_or(ReplayError::ReplayLimit)?;
        if let Some(existing) = self.values.get(&base) {
            return if existing == &snapshot {
                Ok(())
            } else {
                Err(ReplayError::InvalidOrderedBase)
            };
        }
        let next_count = self
            .values
            .len()
            .checked_add(1)
            .ok_or(ReplayError::ReplayLimit)?;
        let next_bytes = self
            .bytes
            .checked_add(snapshot_bytes)
            .ok_or(ReplayError::ReplayLimit)?;
        if next_count > MAX_MATERIALIZED_ORDERED_SNAPSHOTS
            || next_bytes > MAX_MATERIALIZED_ORDERED_SNAPSHOT_BYTES
        {
            return Err(ReplayError::ReplayLimit);
        }
        self.values.insert(base, snapshot);
        self.bytes = next_bytes;
        Ok(())
    }

    fn singleton(
        base: OrderedBase,
        snapshot: MaterializedOrderedSnapshot,
    ) -> Result<Self, ReplayValidationError> {
        let mut snapshots = Self::default();
        snapshots.insert(base, snapshot)?;
        Ok(snapshots)
    }

    fn validate(&self) -> Result<(), ReplayValidationError> {
        #[cfg(feature = "experimental-state-blocks")]
        for (base, snapshot) in &self.values {
            snapshot.validate(*base)?;
        }
        let bytes = self.values.values().try_fold(0usize, |bytes, snapshot| {
            bytes
                .checked_add(snapshot.control.len())
                .and_then(|bytes| bytes.checked_add(snapshot.linear.len()))
                .ok_or(ReplayError::ReplayLimit)
        })?;
        if bytes != self.bytes {
            Err(ReplayError::InvalidRecord)
        } else if self.values.len() > MAX_MATERIALIZED_ORDERED_SNAPSHOTS
            || bytes > MAX_MATERIALIZED_ORDERED_SNAPSHOT_BYTES
        {
            Err(ReplayError::ReplayLimit)
        } else {
            Ok(())
        }
    }
}

/// Exact checkpoint-relative dependency budget for the durable suffix.
///
/// The identity sets are retained in the opaque materialization so live
/// publication charges the same unique records as crash recovery. A
/// checkpoint is the only operation which resets this value.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct ReplaySuffixBudget {
    entries: usize,
    bytes: usize,
    ordered: BTreeSet<OrderedEntryId>,
    local: BTreeSet<LocalEntryId>,
    merge: BTreeSet<MergeEventId>,
    frontiers: BTreeSet<MergeFrontierId>,
    seals: BTreeSet<MergeSealId>,
}

impl ReplaySuffixBudget {
    fn add_entry(&mut self, inserted: bool, encoded: usize) -> Result<(), ReplayValidationError> {
        if !inserted {
            return Ok(());
        }
        self.entries = self
            .entries
            .checked_add(1)
            .ok_or(ReplayError::ReplayLimit)?;
        self.bytes = self
            .bytes
            .checked_add(encoded)
            .ok_or(ReplayError::ReplayLimit)?;
        self.validate_limits()
    }

    fn ordered(
        &mut self,
        id: OrderedEntryId,
        entry: &OrderedEntry,
    ) -> Result<(), ReplayValidationError> {
        let inserted = self.ordered.insert(id);
        self.add_entry(inserted, entry.encode().len())
    }

    fn local(&mut self, id: LocalEntryId, entry: &LocalEntry) -> Result<(), ReplayValidationError> {
        let inserted = self.local.insert(id);
        self.add_entry(inserted, entry.encode().len())
    }

    fn merge(&mut self, id: MergeEventId, event: &MergeEvent) -> Result<(), ReplayValidationError> {
        let inserted = self.merge.insert(id);
        self.add_entry(inserted, event.encode().len())
    }

    fn frontier(&mut self, frontier: &MergeFrontier) -> Result<(), ReplayValidationError> {
        if self.frontiers.insert(frontier.id()) {
            self.bytes = self
                .bytes
                .checked_add(frontier.encode().len())
                .ok_or(ReplayError::ReplayLimit)?;
        }
        self.validate_limits()
    }

    fn seal(&mut self, seal: &MergeSeal) -> Result<(), ReplayValidationError> {
        if self.seals.insert(seal.id()) {
            self.bytes = self
                .bytes
                .checked_add(seal.encode().len())
                .ok_or(ReplayError::ReplayLimit)?;
        }
        self.validate_limits()
    }

    fn validate_limits(&self) -> Result<(), ReplayValidationError> {
        if self.entries > MAX_REPLAY_SUFFIX_ENTRIES || self.bytes > MAX_REPLAY_SUFFIX_BYTES {
            Err(ReplayError::ReplayLimit)
        } else {
            Ok(())
        }
    }

    fn validate(&self) -> Result<(), ReplayValidationError> {
        let indexed_entries = self
            .ordered
            .len()
            .checked_add(self.local.len())
            .and_then(|count| count.checked_add(self.merge.len()))
            .ok_or(ReplayError::ReplayLimit)?;
        if self.entries != indexed_entries {
            Err(ReplayError::InvalidRecord)
        } else {
            self.validate_limits()
        }
    }
}

/// Authenticated aggregate initialized from the exact durable head's genesis
/// or checkpoint closure and advanced through its complete bounded suffix.
/// Every field is private: callers may inspect facts but cannot substitute
/// state bytes or cursors when preparing a publication.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReplayMaterialization {
    /// Explicit format/provenance, never inferred from component bytes. Entries
    /// must come from authenticated lane manifests or captured replay steps.
    #[cfg(feature = "experimental-state-blocks")]
    external_roots: BTreeMap<PersistedLane, super::journal::ExternalStateRoot>,
    clean_management: Option<super::journal::CleanManagementEvidence>,
    heads_id: JournalHeadsId,
    heads: JournalHeads,
    replayed_root: Option<ReplayedRootJournalIdentity>,
    state: RuntimeState,
    final_system_authority_write: Option<ReplayMaterializedSystemAuthorityWrite>,
    ordered_snapshots: MaterializedOrderedSnapshots,
    merge_roots: Vec<SealedMergeRoot>,
    /// Retained roots of the authenticated replay boundary. A new Merge
    /// branch may descend from these roots or any loaded descendant, but not
    /// from a pruned internal ancestor. An empty set is the post-genesis
    /// boundary and permits independent height-one roots.
    merge_boundary_roots: BTreeSet<MergeEventId>,
    merge_boundary_ancestry: BTreeSet<MergeEventId>,
    merge_boundary_state: Vec<u8>,
    merge_boundary_invocations: InvocationIndexId,
    /// Exact live transition-proof projection at the newest authenticated
    /// Merge fence (or at the checkpoint/genesis replay boundary when no
    /// newer fence exists). Merge rebuilds start here rather than trusting
    /// the current physical projection, which already contains the old
    /// canonical suffix being replaced.
    merge_boundary_transition_proofs: ReplayTransitionProofShadow,
    merge_ancestry: BTreeSet<MergeEventId>,
    fence: Option<MergeFence>,
    artifacts: ArtifactClosure,
    suffix_budget: ReplaySuffixBudget,
    replay_boundary: OrderedBase,
    /// Present only after a verified common certificate authenticates a
    /// semantic ancestry base older than this physical checkpoint boundary.
    common_ancestry_boundary: Option<CertifiedCommonAncestryBoundary>,
    fence_ancestry: FenceAncestryEvidence,
    /// Complete proof index authenticated by `heads.transition_proofs`.
    /// The boundary shadow is replayed to this exact live projection while
    /// materializing the bounded suffix; immutable records remain storage
    /// authority and are not duplicated in the shadow.
    transition_proofs: TransitionProofIndexManifest,
    transition_proof_shadow: ReplayTransitionProofShadow,
    /// Canonical Merge acknowledgement projection to install at the next
    /// authenticated fence. It may differ from the physical AJP3 live map
    /// while an Applied acknowledgement remains provisional; checkpointing
    /// is forbidden until the two projections converge.
    pending_transition_proof_final_shadow: ReplayTransitionProofShadow,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct CertifiedCommonAncestryBoundary {
    checkpoint: CheckpointId,
    semantic_base: OrderedBase,
}

/// Private replay projection of the one-live-proof-per-invocation map.
///
/// This deliberately carries no caller-provided record IDs. It is seeded
/// only from a decoded AJP3 manifest and advanced by replay-validated
/// lifecycle steps. Storage independently derives the same projection from
/// the authenticated predecessor index before accepting the head CAS.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct ReplayTransitionProofShadow {
    genesis: AgentJournalGenesisId,
    /// Purpose-tagged cumulative terminal-invocation history authenticated by
    /// the AJP3 image at this exact replay boundary. Membership is loaded only
    /// for the bounded lifecycle inputs about to be replayed.
    retired_root: Option<InvocationHistoryNodeId>,
    states: BTreeMap<crate::agent_sdk::InvocationId, ReplayTransitionProofState>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ReplayTransitionProofState {
    key: Option<crate::agent_sdk::proof::TransitionProofKey>,
    origin: ReplayTransitionProofOrigin,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ReplayTransitionProofOrigin {
    Boundary,
    Position(ReplayPosition),
}

impl ReplayTransitionProofShadow {
    fn from_manifest(manifest: &TransitionProofIndexManifest) -> Self {
        Self {
            genesis: manifest.genesis,
            retired_root: manifest.retired_root(),
            states: manifest
                .live_entries()
                .iter()
                .map(|key| {
                    (
                        key.invocation,
                        ReplayTransitionProofState {
                            key: Some(*key),
                            origin: ReplayTransitionProofOrigin::Boundary,
                        },
                    )
                })
                .collect(),
        }
    }

    pub(crate) fn live(
        &self,
        invocation: crate::agent_sdk::InvocationId,
    ) -> Option<crate::agent_sdk::proof::TransitionProofKey> {
        self.states.get(&invocation).and_then(|state| state.key)
    }

    pub(crate) const fn retired_root(&self) -> Option<InvocationHistoryNodeId> {
        self.retired_root
    }

    fn with_retired_root(mut self, retired_root: Option<InvocationHistoryNodeId>) -> Self {
        self.retired_root = retired_root;
        self
    }

    pub(crate) fn live_entries(
        &self,
    ) -> impl Iterator<Item = crate::agent_sdk::proof::TransitionProofKey> + '_ {
        self.states.values().filter_map(|state| state.key)
    }

    fn live_matches_manifest(&self, manifest: &TransitionProofIndexManifest) -> bool {
        self.genesis == manifest.genesis
            && self
                .states
                .values()
                .filter(|state| state.key.is_some())
                .count()
                == manifest.live_entries().len()
            && manifest
                .live_entries()
                .iter()
                .all(|key| self.live(key.invocation) == Some(*key))
    }

    fn matches_manifest(&self, manifest: &TransitionProofIndexManifest) -> bool {
        self.retired_root == manifest.retired_root() && self.live_matches_manifest(manifest)
    }

    /// Compare the logical live/tombstone projection without treating its
    /// replay provenance as durable state. Origins decide how a later Merge
    /// suffix is reconciled, but two shadows have converged for checkpoint
    /// purposes when they carry the same exact key (including explicit
    /// tombstones) for every invocation.
    fn projection_eq(&self, other: &Self) -> bool {
        self.genesis == other.genesis
            && self.retired_root == other.retired_root
            && self.states.len() == other.states.len()
            && self.states.iter().all(|(invocation, state)| {
                other
                    .states
                    .get(invocation)
                    .is_some_and(|other| other.key == state.key)
            })
    }

    fn lifecycle(
        input: &ReplayInput,
    ) -> Option<(
        crate::agent_sdk::InvocationId,
        ReplayTransitionProofLifecycle,
    )> {
        match &input.operation {
            ReplayOperation::CleanInvoke {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                work,
                ..
            } => Some((work.invocation, ReplayTransitionProofLifecycle::Invoke)),
            ReplayOperation::CleanResume {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                expected_live: Some(expected),
                work,
                ..
            } if expected.invocation == work.invocation => Some((
                work.invocation,
                ReplayTransitionProofLifecycle::Resume(*expected),
            )),
            ReplayOperation::CleanAcknowledge {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                expected_live: Some(expected),
                work,
                ..
            } if expected.invocation == work.invocation => Some((
                work.invocation,
                ReplayTransitionProofLifecycle::Acknowledge(*expected),
            )),
            _ => None,
        }
    }

    fn admits(
        &self,
        invocation: crate::agent_sdk::InvocationId,
        lifecycle: ReplayTransitionProofLifecycle,
    ) -> bool {
        match lifecycle {
            // An explicit None is an authenticated post-boundary tombstone,
            // not the never-published absence which admits Invoke. This
            // distinction prevents a replaced Merge suffix from running the
            // guest/provider for an invocation retired by a later
            // Ordered/Local publication.
            ReplayTransitionProofLifecycle::Invoke => !self.states.contains_key(&invocation),
            ReplayTransitionProofLifecycle::Resume(expected)
            | ReplayTransitionProofLifecycle::Acknowledge(expected) => {
                self.live(invocation) == Some(expected)
            }
        }
    }

    fn install(
        &mut self,
        key: crate::agent_sdk::proof::TransitionProofKey,
        position: ReplayPosition,
    ) {
        self.states.insert(
            key.invocation,
            ReplayTransitionProofState {
                key: Some(key),
                origin: ReplayTransitionProofOrigin::Position(position),
            },
        );
    }

    fn retire(
        &mut self,
        key: crate::agent_sdk::proof::TransitionProofKey,
        position: ReplayPosition,
    ) -> bool {
        if self.live(key.invocation) != Some(key) {
            return false;
        }
        self.states.insert(
            key.invocation,
            ReplayTransitionProofState {
                key: None,
                origin: ReplayTransitionProofOrigin::Position(position),
            },
        );
        true
    }

    fn seed_terminal(
        &mut self,
        key: crate::agent_sdk::proof::TransitionProofKey,
    ) -> Result<(), ReplayValidationError> {
        if !key.validate() || key.invocation == crate::agent_sdk::InvocationId::ZERO {
            return Err(ReplayError::InvalidRecord);
        }
        if self.live(key.invocation).is_some() {
            return Err(ReplayError::InvalidRecord);
        }
        self.states
            .entry(key.invocation)
            .or_insert(ReplayTransitionProofState {
                key: None,
                origin: ReplayTransitionProofOrigin::Boundary,
            });
        Ok(())
    }

    /// Start a canonical Merge rebuild at its fence projection while
    /// preserving proof edges created by later Ordered/Local publications.
    /// Merge-origin edges belong to the suffix being replayed and therefore
    /// must not make their own boundary-relative lifecycle inputs stale.
    fn with_external_edges_from(mut self, current: &Self) -> Self {
        for (invocation, state) in &current.states {
            if !matches!(
                state.origin,
                ReplayTransitionProofOrigin::Position(ReplayPosition::Merge { .. })
            ) {
                self.states.insert(*invocation, *state);
            }
        }
        self
    }

    /// Reconcile a boundary-relative canonical Merge result with the current
    /// physical projection. Ordered/Local edges published after the boundary
    /// are outside the replaced Merge suffix and therefore win; boundary and
    /// prior-Merge edges are replaced by the newly derived net projection.
    fn reconcile_merge(current: &Self, merge_net: &Self) -> Self {
        let mut reconciled = merge_net.clone();
        for (invocation, state) in &current.states {
            if matches!(
                state.origin,
                ReplayTransitionProofOrigin::Position(ReplayPosition::Ordered { .. })
                    | ReplayTransitionProofOrigin::Position(ReplayPosition::Local { .. })
            ) {
                reconciled.states.insert(*invocation, *state);
            }
        }
        reconciled
    }

    fn as_fence_boundary(&self) -> Self {
        let mut boundary = self.clone();
        for state in boundary.states.values_mut() {
            state.origin = ReplayTransitionProofOrigin::Boundary;
        }
        boundary
    }

    fn as_checkpoint_boundary(&self) -> Self {
        let mut boundary = self.as_fence_boundary();
        // A checkpoint is the only boundary which may compact explicit
        // tombstones. Its authenticated retired_root lazily restores exactly
        // the bounded InvocationIds consulted by later replay.
        boundary.states.retain(|_, state| state.key.is_some());
        boundary
    }
}

impl ReplayMaterialization {
    pub(crate) fn common_checkpoint(&self) -> Option<CheckpointId> {
        self.fence_ancestry.common_checkpoint()
    }

    fn ancestry_boundary_matches(&self) -> bool {
        match self.common_ancestry_boundary {
            None => self.fence_ancestry.checkpoint_base() == self.replay_boundary,
            Some(boundary) => {
                self.heads.checkpoint == Some(boundary.checkpoint)
                    && self.fence_ancestry.common_checkpoint() == Some(boundary.checkpoint)
                    && self.fence_ancestry.checkpoint_base() == boundary.semantic_base
                    && boundary.semantic_base.index <= self.replay_boundary.index
            }
        }
    }

    #[cfg(feature = "std")]
    pub(crate) fn common_snapshot_ancestry(
        &self,
    ) -> Result<super::shared_commit::SharedAgentCommonSnapshotAncestry, JournalStoreError> {
        if !self.ancestry_boundary_matches() {
            return Err(JournalStoreError::Corrupt);
        }
        super::shared_commit::SharedAgentCommonSnapshotAncestry::new(
            self.fence_ancestry.checkpoint_base,
            self.fence_ancestry.ordered_anchor,
        )
        .map_err(|_| JournalStoreError::Corrupt)
    }
    /// Read-only execution gets only authenticated external descriptors at
    /// this exact head. The opaque component bytes are root descriptors, not
    /// a host-side reconstruction of the runtime's private state.
    #[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
    pub(crate) fn external_inspection_lanes(
        &self,
    ) -> Result<Vec<crate::agent_sdk::state_execution::ExternalLaneWork>, JournalStoreError> {
        if self.external_roots.is_empty()
            || self.external_roots.len() > 3
            || self.external_roots.contains_key(&PersistedLane::Control)
        {
            return Err(JournalStoreError::NonCanonical);
        }
        self.external_roots
            .iter()
            .map(|(lane, root)| {
                if root.descriptor.encode() != state_component(&self.state, *lane) {
                    return Err(JournalStoreError::Corrupt);
                }
                Ok(crate::agent_sdk::state_execution::ExternalLaneWork {
                    base: root.descriptor,
                    next: root.descriptor.context(),
                })
            })
            .collect()
    }

    /// Advance only declared Ordered/Local roots using an accepted replay
    /// step. An execution cannot invent a lane's format, and a no-op must keep
    /// the old root-producing identity. Availability and publication are separate.
    #[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
    fn external_roots_after_step(
        &self,
        genesis: &AgentJournalGenesis,
        step: &ReplayStep,
    ) -> Result<BTreeMap<PersistedLane, super::journal::ExternalStateRoot>, ReplayValidationError>
    {
        if genesis.id() != self.heads.genesis
            || self.external_roots.contains_key(&PersistedLane::Control)
        {
            return Err(ReplayError::InvalidRecord);
        }
        if let Some(execution) = &step.external_execution {
            if execution.owning_lane().is_none() {
                if !execution.matches_roots(&self.external_roots)
                    || !matches!(
                        step.position,
                        ReplayPosition::Ordered {
                            merge_seal: Some(_),
                            ..
                        }
                    )
                    || self.external_roots.keys().any(|lane| {
                        state_component(&self.state, *lane) != state_component(&step.state, *lane)
                    })
                {
                    return Err(ReplayError::InvalidRecord);
                }
                return Ok(self.external_roots.clone());
            }
        }
        let lane = match step.position {
            ReplayPosition::Ordered {
                merge_seal: None, ..
            } => PersistedLane::Linear,
            ReplayPosition::Local { .. } => PersistedLane::Local,
            _ => return Err(ReplayError::InvalidPosition),
        };
        // An initial external genesis may declare Merge as well. Carry its
        // authenticated root unchanged through an independent lane mutation;
        // this does not admit Merge execution or an Ordered fence.
        for other in self.external_roots.keys().filter(|other| **other != lane) {
            if state_component(&self.state, *other) != state_component(&step.state, *other) {
                return Err(ReplayError::InvalidRecord);
            }
        }
        if let Some(execution) = &step.external_execution {
            if !execution.matches_roots(&self.external_roots)
                || execution
                    .owning_lane()
                    .ok_or(ReplayError::InvalidRecord)?
                    .base
                    .context()
                    .scope()
                    .lane() as u8
                    != lane.state_lane().ok_or(ReplayError::InvalidRecord)? as u8
                || !self.external_roots.contains_key(&lane)
            {
                return Err(ReplayError::InvalidRecord);
            }
        }
        let mut roots = self.external_roots.clone();
        if roots.contains_key(&lane) {
            let previous =
                self.checkpoint_lane(genesis, lane, state_component(&self.state, lane))?;
            let successor = step.external_lane_successor(genesis, &previous)?;
            roots.insert(
                lane,
                successor.external_root.ok_or(ReplayError::InvalidRecord)?,
            );
        }
        Ok(roots)
    }

    /// Derive a checkpoint projection without erasing a retained external
    /// root's producing runtime/revision. This constructs a record, not an
    /// availability certificate or permission to publish it.
    #[cfg(feature = "std")]
    pub(crate) fn checkpoint_lane(
        &self,
        genesis: &AgentJournalGenesis,
        lane: PersistedLane,
        bytes: &[u8],
    ) -> Result<LaneStateManifest, ReplayValidationError> {
        if genesis.id() != self.heads.genesis {
            return Err(ReplayError::ScopeMismatch);
        }
        let cursor = match lane {
            PersistedLane::Control | PersistedLane::Linear => LaneCursor::Ordered {
                base: self.ordered_base(),
            },
            PersistedLane::Merge => LaneCursor::Merge {
                frontier: self.heads.merge_frontier,
            },
            PersistedLane::Local => LaneCursor::Local {
                node: self.heads.node,
                revision: self.heads.local_revision,
                head: self.heads.local_head,
            },
        };
        let manifest = derive_lane_state(
            self.heads.genesis,
            self.heads.runtime.clone(),
            lane,
            cursor,
            bytes,
        )?;
        #[cfg(feature = "experimental-state-blocks")]
        let manifest = if let Some(root) = self.external_roots.get(&lane) {
            let mut manifest = manifest;
            let node = (lane == PersistedLane::Local).then_some(self.heads.node);
            let expected = super::state_block_store::journal_root_context(
                genesis,
                &root.runtime,
                lane,
                node,
                &root.cursor,
            )
            .map_err(|_| ReplayError::InvalidRecord)?;
            if expected != root.descriptor.context() || bytes != root.descriptor.encode() {
                return Err(ReplayError::InvalidRecord);
            }
            manifest.external_root = Some(root.clone());
            manifest
                .validate()
                .map_err(|_| ReplayError::InvalidRecord)?;
            manifest
        } else {
            manifest
        };
        Ok(manifest)
    }

    pub(crate) fn clean_management_evidence(
        &self,
    ) -> Option<&super::journal::CleanManagementEvidence> {
        self.clean_management.as_ref()
    }

    pub const fn heads_id(&self) -> JournalHeadsId {
        self.heads_id
    }

    pub fn heads(&self) -> &JournalHeads {
        &self.heads
    }

    pub fn state(&self) -> &RuntimeState {
        &self.state
    }

    pub fn runtime(&self) -> &RuntimeBinding {
        &self.heads.runtime
    }

    pub const fn ordered_base(&self) -> OrderedBase {
        OrderedBase {
            index: self.heads.ordered_index,
            head: self.heads.ordered_head,
        }
    }

    pub(crate) const fn replay_boundary(&self) -> OrderedBase {
        self.replay_boundary
    }

    /// Whether an exact prospective delta fits the authenticated composite
    /// post-checkpoint dependency budget. Callers supply encoded record bytes;
    /// the opaque materialization remains the sole authority for already
    /// charged Ordered, Local, Merge, frontier, and seal dependencies.
    pub(crate) fn has_suffix_headroom(
        &self,
        additional_entries: usize,
        additional_bytes: usize,
    ) -> bool {
        self.suffix_budget
            .entries
            .checked_add(additional_entries)
            .is_some_and(|entries| entries <= MAX_REPLAY_SUFFIX_ENTRIES)
            && self
                .suffix_budget
                .bytes
                .checked_add(additional_bytes)
                .is_some_and(|bytes| bytes <= MAX_REPLAY_SUFFIX_BYTES)
    }

    pub const fn merge_frontier(&self) -> MergeFrontierId {
        self.heads.merge_frontier
    }

    /// Whether an immutable Merge object is reachable from the authenticated
    /// materialized head. A journal store may also contain crash-safe staged
    /// objects; mere content presence is deliberately not publication proof.
    pub(crate) fn contains_merge(&self, event: MergeEventId) -> bool {
        self.merge_ancestry.contains(&event)
    }

    pub const fn local_cursor(&self) -> (NodeId, u64, Option<LocalEntryId>) {
        (
            self.heads.node,
            self.heads.local_revision,
            self.heads.local_head,
        )
    }

    pub const fn invocation_indexes(
        &self,
    ) -> (InvocationIndexId, InvocationIndexId, InvocationIndexId) {
        (
            self.heads.ordered_invocations,
            self.heads.merge_invocations,
            self.heads.local_invocations,
        )
    }

    pub fn artifacts(&self) -> &ArtifactClosure {
        &self.artifacts
    }

    /// Attach root provenance only from the exact independently reverified
    /// seal for this already authenticated materialization. Cold store
    /// integration calls this seam in batch 5c; until then reopen remains
    /// deliberately unscoped.
    pub(crate) fn attach_replayed_root(
        &mut self,
        sealed: &ReplaySealedGenesis,
    ) -> Result<(), ReplayValidationError> {
        let identity = sealed.replayed_root_identity()?;
        self.attach_replayed_root_identity(identity)
    }

    fn attach_replayed_root_identity(
        &mut self,
        identity: ReplayedRootJournalIdentity,
    ) -> Result<(), ReplayValidationError> {
        if identity.genesis() != self.heads.genesis
            || identity.outer_admission() != self.heads.admission
        {
            return Err(ReplayError::ScopeMismatch);
        }
        self.replayed_root = Some(identity);
        Ok(())
    }

    pub(crate) const fn replayed_root(&self) -> Option<ReplayedRootJournalIdentity> {
        self.replayed_root
    }
}

/// One prepared CAS and the only successor materialization which may become
/// usable if that CAS succeeds. `publish` consumes the session on every path;
/// a conflict therefore discards all staged root IDs. The exclusive store
/// borrow binds every candidate index path and outcome staged during prepare
/// to the exact store which performs the CAS; safe callers cannot transfer a
/// prepared publication to another store or mutate that store in between.
#[cfg(feature = "std")]
pub struct ReplayPreparedPublication<'store, S: AgentJournalStore> {
    store: &'store mut S,
    sealed: ReplaySealedPublication,
    successor: ReplayMaterialization,
    executions: Vec<ReplayExecutionResult>,
}

/// Maintenance-only availability owner. Not Clone: the exact prepared seal
/// and exclusive store borrow stay together until publication or abandonment.
/// Only storage implementations with explicit availability validation may CAS.
#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
pub(crate) struct AuditedExternalCheckpoint<'store, S: AgentJournalStore> {
    prepared: ReplayPreparedPublication<'store, S>,
    lanes: BTreeSet<LaneStateId>,
    predecessor_lanes: BTreeSet<LaneStateId>,
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
fn supported_external_checkpoint_lane(
    manifest: &LaneStateManifest,
    genesis: Option<&ReplaySealedExternalLocalGenesis>,
) -> bool {
    match manifest.lane {
        PersistedLane::Linear | PersistedLane::Local => true,
        PersistedLane::Merge => genesis.is_some_and(|seal| {
            let initial = seal.lane_manifest(PersistedLane::Merge);
            manifest.genesis == initial.genesis
                && manifest.runtime == initial.runtime
                && manifest.cursor == initial.cursor
                && manifest.state == initial.state
                && manifest.external_root == initial.external_root
        }),
        PersistedLane::Control => false,
    }
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
fn external_checkpoint_lanes<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
) -> Result<BTreeSet<LaneStateId>, JournalStoreError> {
    let checkpoint: CheckpointManifest = store
        .get(heads.checkpoint.ok_or(JournalStoreError::NonCanonical)?)?
        .ok_or(JournalStoreError::MissingObject)?;
    checkpoint
        .lanes
        .iter()
        .filter_map(|lane| match store.get::<LaneStateManifest>(lane.state) {
            Ok(Some(manifest)) if manifest.external_root.is_some() => Some(Ok(lane.state)),
            Ok(Some(_)) => None,
            Ok(None) => Some(Err(JournalStoreError::MissingObject)),
            Err(error) => Some(Err(error)),
        })
        .collect()
}

/// Borrowed validation context minted only by an audited checkpoint owner or
/// an exclusively pinned replay session. Mutation authority additionally binds
/// the exact seal and is enabled only after incremental staging succeeds.
/// It is never persisted, cloned, or constructed from caller-supplied hashes.
#[cfg(feature = "std")]
pub(crate) struct ExternalCheckpointValidation<'a> {
    /// Only a pinned replay session may bind a mutation to this exact borrowed
    /// seal. A checkpoint/root audit alone must never authorize execution CAS.
    #[cfg(feature = "experimental-state-blocks")]
    mutation: Option<(&'a ReplaySealedPublication, bool)>,
    store: JournalStoreInstanceId,
    predecessor: JournalHeadsId,
    successor: JournalHeadsId,
    predecessor_checkpoint: Option<CheckpointId>,
    successor_checkpoint: CheckpointId,
    predecessor_lanes: &'a BTreeSet<LaneStateId>,
    successor_lanes: &'a BTreeSet<LaneStateId>,
}

#[cfg(feature = "std")]
impl ExternalCheckpointValidation<'_> {
    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn permits_mutation(
        &self,
        store: JournalStoreInstanceId,
        publication: &ReplaySealedPublication,
    ) -> bool {
        self.mutation.is_some_and(|(_, staged)| staged)
            && self.permits_pinned_base(store, publication)
    }

    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn permits_pinned_base(
        &self,
        store: JournalStoreInstanceId,
        publication: &ReplaySealedPublication,
    ) -> bool {
        self.store == store
            && self
                .mutation
                .is_some_and(|(seal, _)| core::ptr::eq(seal, publication))
            && self.predecessor == publication.expected
            && self.successor == publication.next.id()
            && self.predecessor_checkpoint == Some(self.successor_checkpoint)
            && publication.next.checkpoint == Some(self.successor_checkpoint)
            && ((publication.mode == ReplayPublicationMode::Canonical
                && publication.shared_ordered_commit.is_none())
                || (matches!(
                    publication.mode,
                    ReplayPublicationMode::SharedOrderedPreserveMerge
                        | ReplayPublicationMode::SharedOrderedInstallFence
                ) && publication
                    .shared_ordered_commit
                    .as_ref()
                    .is_some_and(|binding| {
                        binding.journal_store == store
                            && binding.claim.runtime().is_external_state()
                            && publication.next.local_revision == 0
                            && publication.next.local_head.is_none()
                            && publication.external_execution().is_none_or(|execution| {
                                execution.lanes().len() == 1
                                    && execution.lanes()[0].base.context().scope().lane()
                                        == crate::agent_sdk::StateLane::Linear
                            })
                    })))
            && publication.system_authority_write.is_none()
            && match &publication.anchor {
                ReplayPublicationAnchor::Local(_) => true,
                ReplayPublicationAnchor::Ordered(entry) => {
                    entry.merge_seal.is_none()
                        || (matches!(
                            &entry.input.operation,
                            ReplayOperation::CleanManage {
                                request: crate::agent_sdk::ManagementRequest::Install(_),
                                ..
                            }
                        ) && publication
                            .external_execution()
                            .is_some_and(|execution| execution.owning_lane().is_none()))
                }
                _ => false,
            }
    }
    pub(crate) fn matches_heads(
        &self,
        store: JournalStoreInstanceId,
        heads: &JournalHeads,
    ) -> bool {
        store == self.store
            && ((heads.id() == self.predecessor && heads.checkpoint == self.predecessor_checkpoint)
                || (heads.id() == self.successor
                    && heads.checkpoint == Some(self.successor_checkpoint)))
    }

    pub(crate) fn permits_lane(
        &self,
        store: JournalStoreInstanceId,
        checkpoint: CheckpointId,
        lane: LaneStateId,
    ) -> bool {
        store == self.store
            && ((checkpoint == self.successor_checkpoint && self.successor_lanes.contains(&lane))
                || (Some(checkpoint) == self.predecessor_checkpoint
                    && self.predecessor_lanes.contains(&lane)))
    }
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
impl<'store, S: AgentJournalStore> AuditedExternalCheckpoint<'store, S> {
    pub(crate) fn publish(
        self,
    ) -> Result<
        (
            JournalPublication,
            ReplayMaterialization,
            Vec<ReplayExecutionResult>,
        ),
        JournalStoreError,
    >
    where
        S: super::journal_store::AuditedCheckpointStore,
    {
        self.publish_using(|store, publication, availability| {
            store.publish_audited_checkpoint(publication, availability)
        })
    }

    fn publish_using(
        self,
        publish: impl FnOnce(
            &mut S,
            &ReplaySealedPublication,
            &ExternalCheckpointValidation<'_>,
        ) -> Result<JournalPublication, JournalStoreError>,
    ) -> Result<
        (
            JournalPublication,
            ReplayMaterialization,
            Vec<ReplayExecutionResult>,
        ),
        JournalStoreError,
    > {
        let Self {
            prepared,
            lanes,
            predecessor_lanes,
        } = self;
        let current = prepared
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        if current.id() != prepared.sealed.expected {
            return Err(JournalStoreError::Conflict);
        }
        let availability = ExternalCheckpointValidation {
            mutation: None,
            store: prepared.store.instance_id(),
            predecessor: current.id(),
            successor: prepared.sealed.next.id(),
            predecessor_checkpoint: current.checkpoint,
            successor_checkpoint: prepared
                .sealed
                .next
                .checkpoint
                .ok_or(JournalStoreError::NonCanonical)?,
            predecessor_lanes: &predecessor_lanes,
            successor_lanes: &lanes,
        };
        let result = publish(prepared.store, &prepared.sealed, &availability)?;
        Ok((result, prepared.successor, prepared.executions))
    }
}

/// Maintenance-only head closure validation for an independently admitted
/// store. Availability is scoped to this call's exclusive borrow; no reusable
/// ticket escapes. This is not replay, origin-ancestry or lifecycle authority.
#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
pub(crate) fn validate_external_checkpoint_heads<S: AgentJournalStore>(
    store: &mut S,
    heads: &JournalHeads,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
) -> Result<(), JournalStoreError> {
    with_external_checkpoint_heads(store, heads, budget, |_, _| Ok(()))
}

/// Keep the audited head's availability under one exclusive borrow through a
/// maintenance action. The context cannot be retained past this call.
#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
pub(crate) fn with_external_checkpoint_heads<S: AgentJournalStore, T>(
    store: &mut S,
    heads: &JournalHeads,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    action: impl FnOnce(
        &mut S,
        Option<&ExternalCheckpointValidation<'_>>,
    ) -> Result<T, JournalStoreError>,
) -> Result<T, JournalStoreError> {
    with_external_checkpoint_heads_inner(store, heads, None, budget, action)
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
pub(crate) fn with_external_genesis_checkpoint_heads<S: AgentJournalStore, T>(
    store: &mut S,
    heads: &JournalHeads,
    genesis: &ReplaySealedExternalLocalGenesis,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    action: impl FnOnce(
        &mut S,
        Option<&ExternalCheckpointValidation<'_>>,
    ) -> Result<T, JournalStoreError>,
) -> Result<T, JournalStoreError> {
    genesis.validate_checkpoint_scope(store, heads)?;
    with_external_checkpoint_heads_inner(store, heads, Some(genesis), budget, action)
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
fn with_external_checkpoint_heads_inner<S: AgentJournalStore, T>(
    store: &mut S,
    heads: &JournalHeads,
    external_genesis: Option<&ReplaySealedExternalLocalGenesis>,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    action: impl FnOnce(
        &mut S,
        Option<&ExternalCheckpointValidation<'_>>,
    ) -> Result<T, JournalStoreError>,
) -> Result<T, JournalStoreError> {
    use super::journal_store::validate_head_targets_with_availability;
    use super::state_block_store::StateBlockStaging;
    let Some(id) = heads.checkpoint else {
        validate_head_targets_with_availability(store, heads, None)?;
        return action(store, None);
    };
    let checkpoint: CheckpointManifest = store.get(id)?.ok_or(JournalStoreError::MissingObject)?;
    checkpoint
        .validate()
        .map_err(|_| JournalStoreError::NonCanonical)?;
    if checkpoint.id() != id || checkpoint.genesis != heads.genesis || checkpoint.lanes.len() != 4 {
        return Err(JournalStoreError::NonCanonical);
    }
    let artifacts: ArtifactClosure = store
        .get(checkpoint.artifacts)?
        .ok_or(JournalStoreError::MissingObject)?;
    if artifacts.id() != checkpoint.artifacts || artifacts.genesis != heads.genesis {
        return Err(JournalStoreError::NonCanonical);
    }
    let mut lanes = BTreeSet::new();
    for lane in &checkpoint.lanes {
        let manifest: LaneStateManifest = store
            .get(lane.state)?
            .ok_or(JournalStoreError::MissingObject)?;
        if manifest.id() != lane.state
            || manifest.genesis != heads.genesis
            || manifest.runtime != checkpoint.runtime
            || manifest.lane != lane.lane
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let Some(root) = &manifest.external_root else {
            continue;
        };
        if !checkpoint.runtime.is_external_state()
            || !supported_external_checkpoint_lane(&manifest, external_genesis)
            || (lane.lane == PersistedLane::Local && lane.node != Some(heads.node))
            || !artifacts.artifacts.contains(&root.runtime.package)
            || !lanes.insert(manifest.id())
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let session = StateBlockStaging::audit_manifest(store, &manifest, budget)?;
        drop(session);
    }
    let validation = ExternalCheckpointValidation {
        mutation: None,
        store: store.instance_id(),
        predecessor: heads.id(),
        successor: heads.id(),
        predecessor_checkpoint: Some(id),
        successor_checkpoint: id,
        predecessor_lanes: &lanes,
        successor_lanes: &lanes,
    };
    validate_head_targets_with_availability(store, heads, Some(&validation))?;
    action(store, Some(&validation))
}

/// Storage fault-injection harness. Audits both exact endpoints under one
/// exclusive borrow; synthetic seals remain confined to tests.
#[cfg(all(test, feature = "std", feature = "experimental-state-blocks"))]
pub(crate) fn with_audited_checkpoint_for_test<S: AgentJournalStore, T>(
    store: &mut S,
    publication: &ReplaySealedPublication,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    action: impl FnOnce(&mut S, &ExternalCheckpointValidation<'_>) -> Result<T, JournalStoreError>,
) -> Result<T, JournalStoreError> {
    let current = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    validate_external_checkpoint_heads(store, &current, budget)?;
    validate_external_checkpoint_heads(store, publication.next(), budget)?;
    let collect = |heads: &JournalHeads| -> Result<BTreeSet<LaneStateId>, JournalStoreError> {
        let Some(id) = heads.checkpoint else {
            return Ok(BTreeSet::new());
        };
        let checkpoint: CheckpointManifest =
            store.get(id)?.ok_or(JournalStoreError::MissingObject)?;
        checkpoint
            .lanes
            .iter()
            .filter_map(|lane| match store.get::<LaneStateManifest>(lane.state) {
                Ok(Some(manifest)) if manifest.external_root.is_some() => Some(Ok(lane.state)),
                Ok(Some(_)) => None,
                Ok(None) => Some(Err(JournalStoreError::MissingObject)),
                Err(error) => Some(Err(error)),
            })
            .collect()
    };
    let predecessor_lanes = collect(&current)?;
    let successor_lanes = collect(publication.next())?;
    let context = ExternalCheckpointValidation {
        mutation: None,
        store: store.instance_id(),
        predecessor: current.id(),
        successor: publication.next().id(),
        predecessor_checkpoint: current.checkpoint,
        successor_checkpoint: publication
            .next()
            .checkpoint
            .ok_or(JournalStoreError::NonCanonical)?,
        predecessor_lanes: &predecessor_lanes,
        successor_lanes: &successor_lanes,
    };
    action(store, &context)
}

/// Authenticated execution facts carried by a prepared journal publication.
/// Durable invocation replies remain in the scoped invocation-result state
/// of the returned successor materialization. Management replies are carried
/// directly for the synchronous publication handoff; these execution facts
/// are not a substitute for authenticated checkpoint recovery evidence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReplayExecutionResult {
    outcome: ReplayStepOutcome,
    result: Option<Result<ActorExecutionReply, ActorExecutionError>>,
    clean_management_result:
        Option<Result<crate::agent_sdk::ManagementReply, crate::agent_sdk::ManagementError>>,
    products: ReplayProducts,
    input: super::journal::ReplayInputId,
    position: ReplayPosition,
}

impl ReplayExecutionResult {
    /// Exact management reply carried across publication, without consulting
    /// private runtime state or an executor's bounded result cache. Checkpoint
    /// persistence is a separate boundary and is not implied by this accessor.
    pub fn clean_management_result(
        &self,
    ) -> Option<&Result<crate::agent_sdk::ManagementReply, crate::agent_sdk::ManagementError>> {
        self.clean_management_result.as_ref()
    }

    pub const fn outcome(&self) -> ReplayStepOutcome {
        self.outcome
    }

    pub fn result(&self) -> Option<&Result<ActorExecutionReply, ActorExecutionError>> {
        self.result.as_ref()
    }

    pub const fn products(&self) -> ReplayProducts {
        self.products
    }

    pub const fn input(&self) -> super::journal::ReplayInputId {
        self.input
    }

    pub const fn position(&self) -> ReplayPosition {
        self.position
    }
}

/// Exact committed input which must be recovered from authenticated state on
/// a response-loss retry. No runtime transition is executed a second time.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ReplayCommittedRecovery {
    input: super::journal::ReplayInputId,
    position: ReplayPosition,
}

/// Authenticated durable state of one scoped invocation identity. A retained
/// result is loaded through the exact ownership root in `ReplayMaterialization`;
/// decoded outcome bytes alone never confer this authority.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReplayInvocationRecovery {
    NotCommitted,
    Pending,
    Retained(Result<ActorExecutionReply, ActorExecutionError>),
    Acknowledged,
    Divergent,
}

impl ReplayCommittedRecovery {
    pub const fn input(self) -> super::journal::ReplayInputId {
        self.input
    }

    pub const fn position(self) -> ReplayPosition {
        self.position
    }
}

#[cfg(feature = "std")]
impl<'store, S: AgentJournalStore> ReplayPreparedPublication<'store, S> {
    /// Audit external roots only for checkpoint maintenance, never as a
    /// substitute for incremental availability on ordinary request publication.
    /// Consuming preparation prevents callers from changing its seal or running
    /// GC between this audit and the eventual storage handoff.
    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn audit_external_checkpoint(
        self,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<AuditedExternalCheckpoint<'store, S>, JournalStoreError> {
        self.audit_external_checkpoint_inner(None, budget)
    }

    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn audit_external_checkpoint_from_genesis(
        self,
        genesis: &ReplaySealedExternalLocalGenesis,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<AuditedExternalCheckpoint<'store, S>, JournalStoreError> {
        genesis.validate_checkpoint_scope(self.store, self.sealed.next())?;
        self.audit_external_checkpoint_inner(Some(genesis), budget)
    }

    #[cfg(feature = "experimental-state-blocks")]
    fn audit_external_checkpoint_inner(
        self,
        external_genesis: Option<&ReplaySealedExternalLocalGenesis>,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<AuditedExternalCheckpoint<'store, S>, JournalStoreError> {
        use super::state_block_store::{StateBlockStaging, journal_root_context};
        let checkpoint = self
            .sealed
            .checkpoint_validation()
            .ok_or(JournalStoreError::NonCanonical)?;
        if self.sealed.mode != ReplayPublicationMode::Canonical
            || self.sealed.shared_ordered_commit.is_some()
            || self.sealed.shared_merge_projection.is_some()
            || self.sealed.next.checkpoint != Some(checkpoint.manifest().id())
            || self.successor.heads != self.sealed.next
            || self.successor.heads_id != self.sealed.next.id()
            || !self.executions.is_empty()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let current = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        if current.id() != self.sealed.expected {
            return Err(JournalStoreError::Conflict);
        }
        if !current.runtime.is_external_state()
            || !matches!(self.sealed.anchor(), ReplayPublicationAnchor::Checkpoint(manifest)
                if manifest == checkpoint.manifest())
            || checkpoint.lanes().len() != checkpoint.manifest().lanes.len()
            || !checkpoint
                .lanes()
                .iter()
                .zip(&checkpoint.manifest().lanes)
                .all(|((lane, _), expected)| lane == expected)
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let genesis = self
            .store
            .genesis()?
            .ok_or(JournalStoreError::NotInitialized)?;
        if genesis.id() != current.genesis || checkpoint.manifest().genesis != current.genesis {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let mut lanes = BTreeSet::new();
        for (lane, manifest) in checkpoint.lanes() {
            let Some(root) = &manifest.external_root else {
                continue;
            };
            manifest
                .validate()
                .map_err(|_| JournalStoreError::NonCanonical)?;
            if lane.state != manifest.id()
                || lane.lane != manifest.lane
                || manifest.runtime != current.runtime
                || manifest.genesis != current.genesis
                || !supported_external_checkpoint_lane(manifest, external_genesis)
                || !checkpoint
                    .artifacts()
                    .artifacts
                    .contains(&root.runtime.package)
                || !lanes.insert(manifest.id())
            {
                return Err(JournalStoreError::NonCanonical);
            }
            let node = (manifest.lane == PersistedLane::Local).then_some(current.node);
            let context =
                journal_root_context(&genesis, &root.runtime, manifest.lane, node, &root.cursor)
                    .map_err(|_| JournalStoreError::ScopeMismatch)?;
            let encoded = root.descriptor.encode();
            let (stored, _, _) = self.store.load_blob_with_work_limit(
                JournalBlobClass::LaneState,
                &manifest.state,
                encoded.len() as u64,
                2,
            )?;
            if stored.ok_or(JournalStoreError::MissingObject)? != encoded {
                return Err(JournalStoreError::Corrupt);
            }
            let session = StateBlockStaging::audit_base(
                self.store,
                root.descriptor,
                context,
                root.descriptor.commitment(),
                budget,
            )?;
            drop(session);
        }
        if lanes.is_empty() {
            return Err(JournalStoreError::NonCanonical);
        }
        // Storage validates both the existing head's checkpoint and its
        // successor. Auditing only the new root cannot establish availability
        // of old branches no longer reachable from that successor.
        let mut predecessor_lanes = BTreeSet::new();
        if let Some(id) = current.checkpoint {
            let previous: CheckpointManifest = self
                .store
                .get(id)?
                .ok_or(JournalStoreError::MissingObject)?;
            if previous.id() != id
                || previous.genesis != current.genesis
                || previous.lanes.len() != 4
            {
                return Err(JournalStoreError::NonCanonical);
            }
            previous
                .validate()
                .map_err(|_| JournalStoreError::NonCanonical)?;
            let artifacts: ArtifactClosure = self
                .store
                .get(previous.artifacts)?
                .ok_or(JournalStoreError::MissingObject)?;
            if artifacts.id() != previous.artifacts || artifacts.genesis != current.genesis {
                return Err(JournalStoreError::NonCanonical);
            }
            for lane in &previous.lanes {
                let manifest: LaneStateManifest = self
                    .store
                    .get(lane.state)?
                    .ok_or(JournalStoreError::MissingObject)?;
                if manifest.id() != lane.state
                    || manifest.lane != lane.lane
                    || manifest.runtime != previous.runtime
                    || manifest.genesis != current.genesis
                {
                    return Err(JournalStoreError::NonCanonical);
                }
                let Some(root) = &manifest.external_root else {
                    continue;
                };
                if !supported_external_checkpoint_lane(&manifest, external_genesis)
                    || (lane.lane == PersistedLane::Local && lane.node != Some(current.node))
                    || !artifacts.artifacts.contains(&root.runtime.package)
                    || !predecessor_lanes.insert(manifest.id())
                {
                    return Err(JournalStoreError::NonCanonical);
                }
                // An identical manifest was already audited under this same
                // exclusive borrow. Otherwise charge the shared maintenance
                // budget for the independently selected predecessor root.
                if !lanes.contains(&manifest.id()) {
                    let session = StateBlockStaging::audit_manifest(self.store, &manifest, budget)?;
                    drop(session);
                }
            }
        }
        Ok(AuditedExternalCheckpoint {
            prepared: self,
            lanes,
            predecessor_lanes,
        })
    }

    #[cfg(test)]
    fn with_staged_transition_proofs_for_test(
        self,
        staged: Vec<StagedTransitionProof>,
    ) -> Result<Self, JournalStoreError>
    where
        S: TransitionProofPublicationStore,
    {
        let batch = JournalVerifiedTransitionPublisher::new(&mut *self.store)
            .stage_apply_batch(&self.sealed, staged)?;
        self.with_transition_proof_batch(batch)
    }

    /// Attach the store-staged proof delta to both halves of the prepared
    /// publication. The successor materialization is returned to callers
    /// after CAS, so updating only the sealed envelope would expose stale
    /// heads even though storage durably installed the new AJP3 root.
    pub(crate) fn with_transition_proof_batch(
        mut self,
        batch: StagedTransitionProofBatch,
    ) -> Result<Self, JournalStoreError> {
        if self.successor.heads != self.sealed.next
            || self.successor.heads_id != self.sealed.next.id()
        {
            return Err(JournalStoreError::Corrupt);
        }
        let next_transition_proofs = batch.next().clone();
        let next_shadow = self
            .successor
            .transition_proof_shadow
            .clone()
            .with_retired_root(next_transition_proofs.retired_root());
        if !next_shadow.matches_manifest(&next_transition_proofs) {
            return Err(JournalStoreError::NonCanonical);
        }
        let installs_fence = matches!(
            self.sealed.anchor(),
            ReplayPublicationAnchor::Ordered(entry) if entry.merge_seal.is_some()
        );
        self.sealed = self.sealed.with_transition_proof_batch(batch)?;
        self.successor.heads = self.sealed.next.clone();
        self.successor.heads_id = self.successor.heads.id();
        self.successor.transition_proofs = next_transition_proofs;
        self.successor.transition_proof_shadow = next_shadow;
        self.successor.pending_transition_proof_final_shadow = self
            .successor
            .pending_transition_proof_final_shadow
            .clone()
            .with_retired_root(self.successor.transition_proofs.retired_root());
        if matches!(self.sealed.anchor(), ReplayPublicationAnchor::Checkpoint(_)) {
            self.successor.transition_proof_shadow = self
                .successor
                .transition_proof_shadow
                .as_checkpoint_boundary();
            self.successor.merge_boundary_transition_proofs =
                self.successor.transition_proof_shadow.clone();
            self.successor.pending_transition_proof_final_shadow =
                self.successor.transition_proof_shadow.clone();
        } else if installs_fence {
            self.successor.merge_boundary_transition_proofs =
                self.successor.transition_proof_shadow.as_fence_boundary();
            self.successor.pending_transition_proof_final_shadow =
                self.successor.transition_proof_shadow.as_fence_boundary();
        }
        Ok(self)
    }

    pub fn publish(
        self,
    ) -> Result<
        (
            JournalPublication,
            ReplayMaterialization,
            Vec<ReplayExecutionResult>,
        ),
        JournalStoreError,
    > {
        #[cfg(feature = "experimental-state-blocks")]
        if self.sealed.external_execution().is_some() {
            return Err(JournalStoreError::Unavailable);
        }
        if self.sealed.mode != ReplayPublicationMode::Canonical
            || self.sealed.shared_ordered_commit.is_some()
            || self.sealed.system_authority_write.is_some()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let publication = self.store.publish(&self.sealed)?;
        Ok((publication, self.successor, self.executions))
    }
}

/// Owned Shared checkpoint plan. Candidate construction may stage the
/// immutable predecessor-head snapshot and compact proof-index object needed
/// by the eventual CAS. External voting may also stage immutable descriptor
/// blobs for a borrowed root audit. Only a quorum-verified snapshot capability
/// may publish the mutable head.
#[cfg(feature = "std")]
pub(crate) struct PreparedSharedCheckpoint {
    sealed: ReplaySealedPublication,
    successor: ReplayMaterialization,
    lane_blobs: Vec<(BlobRef, Vec<u8>)>,
}

/// A complete re-audited destination image. Unlike decoded portable bytes,
/// this capability has been checked against the exact signed physical binding
/// and the common state's opaque lane commitments before filesystem writes.
#[cfg(feature = "std")]
pub(crate) struct ValidatedCommonCheckpoint {
    image: super::journal_store::PortableJournalCheckpoint,
    verified: VerifiedSharedAgentSnapshot,
}

#[cfg(feature = "std")]
impl ValidatedCommonCheckpoint {
    pub(crate) fn image(&self) -> &super::journal_store::PortableJournalCheckpoint {
        &self.image
    }
    pub(crate) fn verified(&self) -> &VerifiedSharedAgentSnapshot {
        &self.verified
    }
}

#[cfg(feature = "std")]
impl PreparedSharedCheckpoint {
    /// Re-audit a maintenance candidate before this replica votes. Only
    /// immutable descriptor blobs are staged; this returns no reusable block
    /// availability capability and does not change the journal head.
    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn audit_external_shared<S: AgentJournalStore>(
        self,
        store: &mut S,
        genesis: &ReplaySealedExternalGenesis,
        pin: &SharedExternalAvailability,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<Self, JournalStoreError> {
        let lane_blobs = self.lane_blobs.clone();
        let audited = self.audit_external_shared_inner(store, genesis, pin, budget)?;
        let ReplayPreparedPublication {
            sealed, successor, ..
        } = audited.prepared;
        Ok(Self {
            sealed,
            successor,
            lane_blobs,
        })
    }

    #[cfg(feature = "experimental-state-blocks")]
    fn audit_external_shared_inner<'store, S: AgentJournalStore>(
        self,
        store: &'store mut S,
        genesis: &ReplaySealedExternalGenesis,
        pin: &SharedExternalAvailability,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<AuditedExternalCheckpoint<'store, S>, JournalStoreError> {
        if !genesis.is_shared()
            || pin.is_poisoned()
            || pin.store != store.instance_id()
            || pin.epoch != store.validation_epoch()
            || pin.heads != self.sealed.expected
        {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let durable_heads = store.heads().map_err(|error| {
            pin.invalidate();
            error
        })?;
        if durable_heads.map(|heads| heads.id()) != Some(pin.heads) {
            // A stale plan was refused above without touching availability.
            // This mismatch instead concerns the admitted owner's physical head.
            pin.invalidate();
            return Err(JournalStoreError::ScopeMismatch);
        }
        aggregate::validate_external_common_checkpoint_profile(store, &self.successor, genesis)
            .map_err(|error| {
                // The profile also reads physical genesis/frontier metadata.
                // Failed reads revoke availability before the block audit starts.
                if matches!(
                    error,
                    JournalStoreError::MissingObject
                        | JournalStoreError::Corrupt
                        | JournalStoreError::Unavailable
                        | JournalStoreError::NonCanonical
                ) {
                    pin.invalidate();
                }
                error
            })?;
        for (reference, bytes) in &self.lane_blobs {
            store.put_blob(JournalBlobClass::LaneState, reference, bytes)?;
        }
        ReplayPreparedPublication {
            store,
            sealed: self.sealed,
            successor: self.successor,
            executions: Vec::new(),
        }
        .audit_external_checkpoint_from_genesis(genesis, budget)
        .map_err(|error| {
            // Once the physical audit starts, failed I/O or malformed/missing
            // closure revokes cached availability. A caller's exhausted audit
            // budget alone does not prove the admitted root became unavailable.
            if error != JournalStoreError::LimitExceeded {
                pin.invalidate();
            }
            error
        })
    }

    /// Publish a quorum-bound external checkpoint under the same exclusive
    /// borrow as both root audits. An ambiguous CAS revokes the old serving pin;
    /// only an exact durable success may replace it with the new checkpoint pin.
    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn publish_external_shared<S: AgentJournalStore>(
        self,
        store: &mut S,
        verified: &VerifiedSharedAgentSnapshot,
        genesis: &ReplaySealedExternalGenesis,
        pin: &mut SharedExternalAvailability,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<ReplayMaterialization, JournalStoreError> {
        self.validate_common_claim(verified.claim())?;
        let ExternalGenesisAdmission::Shared(trusted) = &genesis.admission else {
            return Err(JournalStoreError::ScopeMismatch);
        };
        if store.instance_id().as_bytes() != &verified.claim().journal_store().0
            || trusted.committee() != verified.claim().active_committee()
        {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let audited = self.audit_external_shared_inner(store, genesis, pin, budget)?;
        let checkpoint_lanes = audited.lanes.clone();
        let store_id = audited.prepared.store.instance_id();
        let epoch = audited.prepared.store.validation_epoch();
        pin.poisoned = true;
        let (publication, successor, _) =
            audited.publish_using(|store, publication, availability| {
                let result = store.publish_external_shared_checkpoint(publication, availability)?;
                if !result.heads_advanced && store.heads()?.as_ref() != Some(publication.next()) {
                    return Err(JournalStoreError::Corrupt);
                }
                Ok(result)
            })?;
        let _ = publication;
        *pin = SharedExternalAvailability {
            store: store_id,
            epoch,
            heads: successor.heads_id(),
            checkpoint_lanes,
            poisoned: false,
            invalidated: core::sync::atomic::AtomicBool::new(false),
        };
        Ok(successor)
    }

    pub(crate) fn validate_common_claim(
        &self,
        claim: &SharedAgentSnapshotClaim,
    ) -> Result<(), JournalStoreError> {
        self.validate_claim(claim)?;
        let ordered = claim.ordered();
        let heads = self.successor.heads();
        let state = self.successor.state();
        ordered
            .control()
            .verify_state(&state.control)
            .map_err(|_| JournalStoreError::Corrupt)?;
        ordered
            .linear()
            .verify_state(&state.linear)
            .map_err(|_| JournalStoreError::Corrupt)?;
        ordered
            .merge()
            .verify_state(&state.merge)
            .map_err(|_| JournalStoreError::Corrupt)?;
        if ordered.ordered_invocations() != heads.ordered_invocations
            || ordered.merge_invocations() != heads.merge_invocations
            || ordered.artifacts() != self.successor.artifacts().id()
            || ordered.merge_frontier() != heads.merge_frontier
            || ordered.merge_fence() != heads.merge_fence
            || ordered.merge_seal() != heads.merge_seal
        {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(())
    }

    pub(crate) fn with_transition_proof_batch(
        mut self,
        batch: StagedTransitionProofBatch,
    ) -> Result<Self, JournalStoreError> {
        if self.successor.heads != self.sealed.next
            || self.successor.heads_id != self.sealed.next.id()
        {
            return Err(JournalStoreError::Corrupt);
        }
        let next_transition_proofs = batch.next().clone();
        let next_shadow = self
            .successor
            .transition_proof_shadow
            .clone()
            .with_retired_root(next_transition_proofs.retired_root());
        if !next_shadow.matches_manifest(&next_transition_proofs) {
            return Err(JournalStoreError::NonCanonical);
        }
        self.sealed = self.sealed.with_transition_proof_batch(batch)?;
        self.successor.heads = self.sealed.next.clone();
        self.successor.heads_id = self.successor.heads.id();
        self.successor.transition_proofs = next_transition_proofs;
        self.successor.transition_proof_shadow = next_shadow.as_checkpoint_boundary();
        self.successor.merge_boundary_transition_proofs =
            self.successor.transition_proof_shadow.clone();
        self.successor.pending_transition_proof_final_shadow =
            self.successor.transition_proof_shadow.clone();
        Ok(self)
    }

    pub(crate) fn predecessor_heads(&self) -> JournalHeadsId {
        self.sealed.expected
    }

    pub(crate) fn next_heads(&self) -> &JournalHeads {
        self.sealed.next()
    }

    pub(crate) fn checkpoint(&self) -> &ReplaySealedCheckpoint {
        self.sealed
            .checkpoint_validation()
            .expect("Shared checkpoint plans always carry validation")
    }

    pub(crate) fn lane_roots(
        &self,
    ) -> Option<(LaneStateId, LaneStateId, LaneStateId, LaneStateId)> {
        let mut roots = [None; 4];
        for (lane, state) in self.checkpoint().lanes() {
            let index = match lane.lane {
                PersistedLane::Control => 0,
                PersistedLane::Linear => 1,
                PersistedLane::Merge => 2,
                PersistedLane::Local if lane.node == Some(self.successor.heads.node) => 3,
                PersistedLane::Local => return None,
            };
            if roots[index].replace(state.id()).is_some() {
                return None;
            }
        }
        Some((roots[0]?, roots[1]?, roots[2]?, roots[3]?))
    }

    pub(crate) fn validate_claim(
        &self,
        claim: &SharedAgentSnapshotClaim,
    ) -> Result<(), JournalStoreError> {
        let checkpoint = self.checkpoint();
        let manifest = checkpoint.manifest();
        let mut control = None;
        let mut linear = None;
        let mut merge = None;
        let mut local = None;
        for (lane, state) in checkpoint.lanes() {
            match lane.lane {
                PersistedLane::Control if lane.node.is_none() => control = Some(state.id()),
                PersistedLane::Linear if lane.node.is_none() => linear = Some(state.id()),
                PersistedLane::Merge if lane.node.is_none() => merge = Some(state.id()),
                PersistedLane::Local if lane.node == Some(self.successor.heads.node) => {
                    local = Some(state.id())
                }
                _ => return Err(JournalStoreError::NonCanonical),
            }
        }
        if claim.checkpoint_predecessor() != self.sealed.expected
            || claim.journal_heads() != self.successor.heads_id
            || claim.checkpoint() != manifest.id()
            || claim.local_node() != self.successor.heads.node
            || control != Some(claim.control())
            || linear != Some(claim.linear())
            || merge != Some(claim.merge())
            || local != Some(claim.local())
            || claim.ordered_invocations() != self.successor.heads.ordered_invocations
            || claim.merge_invocations() != self.successor.heads.merge_invocations
            || claim.local_invocations() != self.successor.heads.local_invocations
            || claim.artifacts() != manifest.artifacts
            || self.successor.artifacts.id() != manifest.artifacts
            || manifest.ordered_index != claim.ordered().ordered().index
            || manifest.ordered_head != claim.ordered().ordered().head
            || manifest.runtime != *claim.ordered().runtime()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        Ok(())
    }

    pub(crate) fn publish_shared<S: AgentJournalStore>(
        self,
        store: &mut S,
        verified: &VerifiedSharedAgentSnapshot,
    ) -> Result<ReplayMaterialization, JournalStoreError> {
        self.validate_claim(verified.claim())?;
        if store.instance_id().as_bytes() != &verified.claim().journal_store().0 {
            return Err(JournalStoreError::ScopeMismatch);
        }
        for (reference, bytes) in &self.lane_blobs {
            store.put_blob(JournalBlobClass::LaneState, reference, bytes)?;
        }
        let publication = store.publish(&self.sealed)?;
        if !publication.heads_advanced && store.heads()?.as_ref() != Some(self.sealed.next()) {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(self.successor)
    }
}

/// Non-clonable holder of one exact pre-publication Shared reservation. An
/// evidence ledger may reissue equivalent `(store, route, slot, payload)`
/// reservations after failure; safety comes from the bound physical store,
/// idempotent exact journal CAS, and single durable ledger anchor rather than
/// from global bearer uniqueness. The reservation remains outside the
/// clonable sealed-store token and crosses into the receipt only after CAS.
#[cfg(feature = "std")]
pub(crate) struct PreparedSharedOrderedPublication<'store, S: AgentJournalStore> {
    inner: ReplayPreparedPublication<'store, S>,
    authority: CommittedSharedOrdered,
    #[cfg(feature = "experimental-state-blocks")]
    external: Option<SharedExternalPublication<'store>>,
}

/// Availability retained by the exclusive Shared journal owner after full
/// authenticated recovery. It is not a transferable import/root certificate.
/// The owner must not expose mutable storage or run GC while this pin is live.
#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
pub(crate) struct SharedExternalAvailability {
    store: JournalStoreInstanceId,
    epoch: u64,
    heads: JournalHeadsId,
    checkpoint_lanes: BTreeSet<LaneStateId>,
    poisoned: bool,
    invalidated: core::sync::atomic::AtomicBool,
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
impl SharedExternalAvailability {
    /// A failed read after admission revokes every historical availability
    /// assertion until a fresh owner independently audits the durable store.
    pub(crate) fn invalidate(&self) {
        self.invalidated
            .store(true, core::sync::atomic::Ordering::Relaxed);
    }

    fn is_poisoned(&self) -> bool {
        self.poisoned || self.invalidated.load(core::sync::atomic::Ordering::Relaxed)
    }

    pub(crate) fn require_current<S: AgentJournalStore>(
        &self,
        store: &S,
        materialization: &ReplayMaterialization,
    ) -> Result<(), JournalStoreError> {
        if self.is_poisoned()
            || self.store != store.instance_id()
            || self.epoch != store.validation_epoch()
            || self.heads != materialization.heads_id()
        {
            return Err(JournalStoreError::Unavailable);
        }
        let durable_heads = store.heads().map_err(|error| {
            self.invalidate();
            error
        })?;
        if durable_heads.as_ref() != Some(materialization.heads()) {
            // Caller identity/head mismatches above do not revoke a healthy
            // pin. Failed physical reads require a fresh independent owner audit.
            self.invalidate();
            return Err(JournalStoreError::Unavailable);
        }
        Ok(())
    }
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
struct SharedExternalPublication<'a> {
    availability: &'a mut SharedExternalAvailability,
    budget: crate::agent_sdk::state_blocks::ReadBudget,
}

#[cfg(feature = "std")]
impl<'store, S: AgentJournalStore> PreparedSharedOrderedPublication<'store, S> {
    #[cfg(test)]
    pub(crate) fn stage_binding_before_heads_for_test(
        self,
        include_anchor: bool,
    ) -> Result<(), JournalStoreError>
    where
        S: SharedOrderedCommitStore,
    {
        super::journal_store::stage_shared_binding_before_heads_for_test(
            self.inner.store,
            &self.inner.sealed,
            include_anchor,
        )
    }

    #[cfg(test)]
    fn with_staged_transition_proofs_for_test(
        mut self,
        staged: Vec<StagedTransitionProof>,
    ) -> Result<Self, JournalStoreError>
    where
        S: TransitionProofPublicationStore,
    {
        self.inner = self.inner.with_staged_transition_proofs_for_test(staged)?;
        Ok(self)
    }

    pub(crate) fn with_transition_proof_batch(
        mut self,
        batch: StagedTransitionProofBatch,
    ) -> Result<Self, JournalStoreError> {
        self.inner = self.inner.with_transition_proof_batch(batch)?;
        Ok(self)
    }

    pub(crate) fn publish_shared(
        self,
    ) -> Result<
        (
            JournalPublication,
            ReplayMaterialization,
            Vec<ReplayExecutionResult>,
            PublishedSharedOrdered,
        ),
        JournalStoreError,
    > {
        #[cfg(feature = "experimental-state-blocks")]
        if self.external.is_some() {
            return Err(JournalStoreError::NonCanonical);
        }
        let Self {
            inner, authority, ..
        } = self;
        if !matches!(
            inner.sealed.mode,
            ReplayPublicationMode::SharedOrderedPreserveMerge
                | ReplayPublicationMode::SharedOrderedInstallFence
        ) || inner.sealed.system_authority_write.is_some()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        if inner.store.instance_id() != authority.journal_store {
            return Err(JournalStoreError::NonCanonical);
        }
        let binding = inner
            .sealed
            .shared_ordered_commit
            .as_ref()
            .ok_or(JournalStoreError::NonCanonical)?
            .clone();
        let successor = inner.successor.heads_id;
        let publication = inner.store.publish(&inner.sealed)?;
        let receipt = PublishedSharedOrdered::from_binding(&binding, successor, authority)?;
        Ok((publication, inner.successor, inner.executions, receipt))
    }
}

#[cfg(all(feature = "std", feature = "experimental-state-blocks"))]
impl<'store, S: AgentJournalStore> PreparedSharedOrderedPublication<'store, S> {
    /// Complete block durability precedes the existing Shared binding/CAS and
    /// receipt. Failure poisons the serving availability pin until read-only
    /// authenticated reopen; replay may never repair missing committed blocks.
    pub(crate) fn publish_external_shared(
        self,
    ) -> Result<
        (
            JournalPublication,
            ReplayMaterialization,
            Vec<ReplayExecutionResult>,
            PublishedSharedOrdered,
        ),
        JournalStoreError,
    > {
        let Self {
            inner,
            authority,
            external,
        } = self;
        let SharedExternalPublication {
            availability: pin,
            mut budget,
        } = external.ok_or(JournalStoreError::NonCanonical)?;
        if pin.is_poisoned()
            || pin.store != inner.store.instance_id()
            || pin.epoch != inner.store.validation_epoch()
            || pin.heads != inner.sealed.expected
            || inner.store.heads()?.map(|heads| heads.id()) != Some(pin.heads)
            || inner.store.instance_id() != authority.journal_store
        {
            return Err(JournalStoreError::Conflict);
        }
        let checkpoint = inner
            .sealed
            .next
            .checkpoint
            .ok_or(JournalStoreError::NonCanonical)?;
        let mut validation = ExternalCheckpointValidation {
            mutation: Some((&inner.sealed, false)),
            store: pin.store,
            predecessor: pin.heads,
            successor: inner.sealed.next.id(),
            predecessor_checkpoint: Some(checkpoint),
            successor_checkpoint: checkpoint,
            predecessor_lanes: &pin.checkpoint_lanes,
            successor_lanes: &pin.checkpoint_lanes,
        };
        if !validation.permits_pinned_base(pin.store, &inner.sealed) {
            return Err(JournalStoreError::NonCanonical);
        }
        // No availability is lent after any ambiguous write, including a
        // durable-success/error return from the underlying journal CAS.
        pin.poisoned = true;
        if let Some(execution) = inner.sealed.external_execution() {
            if execution.owning_lane().is_some() {
                let mut staging =
                    super::state_block_store::StateBlockStaging::from_pinned_publication(
                        inner.store,
                        &inner.sealed,
                        &validation,
                    )?;
                staging.stage_execution(execution, &mut budget)?;
                if inner
                    .successor
                    .external_roots
                    .get(&PersistedLane::Linear)
                    .map(|root| root.descriptor)
                    != Some(staging.available())
                {
                    return Err(JournalStoreError::NonCanonical);
                }
            } else if !execution.output().changes().is_empty()
                || !execution.matches_roots(&inner.successor.external_roots)
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        validation.mutation = Some((&inner.sealed, true));
        let binding = inner
            .sealed
            .shared_ordered_commit
            .as_ref()
            .ok_or(JournalStoreError::NonCanonical)?
            .clone();
        let successor = inner.successor.heads_id;
        let publication = inner
            .store
            .publish_available_shared(&inner.sealed, &validation)?;
        let receipt = PublishedSharedOrdered::from_binding(&binding, successor, authority)?;
        pin.heads = successor;
        pin.poisoned = false;
        Ok((publication, inner.successor, inner.executions, receipt))
    }
}

/// Error crossing the independently crash-safe authority-ledger and journal
/// publication boundaries.
#[cfg(all(feature = "std", feature = "storage"))]
